// V65: replay the captured real AGX command (subtype 3, from Metal compute
// on macOS 27). Tail offset references ({off,0x100}) re-pointed into our own
// shmem A data area (or zeroed) since we lack the multi-window pool.
static void p_agxreplay(void) {
    LOG("[v65] AGX command replay");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[rp] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;

    // copy template into A, sanitize offset references:
    memcpy(vaA, agx_cmd_template, 0x358);
    // walk tail qwords: any qword == 0x00000100xxxxxxxx (offset into pool) ->
    // clamp offset into our shmem A (0..0x4000), keeping tag
    for (int i = 0xc8; i + 8 <= 0x358; i += 4) {
        uint64_t v = *(uint64_t *)(vaA + i);
        if ((v >> 32) == 0x100) {
            uint32_t off = (uint32_t)v;
            uint32_t newoff = off % 0x4000;         // stay inside our shmem
            *(uint64_t *)(vaA + i) = ((uint64_t)0x100 << 32) | newoff;
        }
    }
    // segment list in B: count=1, hdr type1|end, pair {0, 0x358}
    memset(vaB, 0, 0x4000);
    *(uint32_t *)(vaB + 0x8) = 1;
    *(uint32_t *)(vaB + 0xc) = 0xC0000001;
    *(uint32_t *)(vaB + 0x10) = 0;
    *(uint32_t *)(vaB + 0x14) = 0x358;
    *outw = 0xdeadbeef;
    kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[rp] replay submit -> kr 0x%08x outw %08x", kt, *outw);
    usleep(500000);
    LOG("[v65] done (alive)");
}

