// V67: faithful replay — exact segment-list framing + nop record + command,
// valid heap pointers in entry +0x10/+0x18.
static void p_agxfaithful(void) {
    LOG("[v67] faithful AGFI replay");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
